import struct, socket
def enc_name(n):
    if n in ('', '.'): return b'\x00'
    out = b''
    for l in n.rstrip('.').split('.'):
        lb = l.encode('latin1')
        out += bytes([len(lb)]) + lb
    return out + b'\x00'
def parse_q(q):
    txid, flags, qd, an, ns, ar = struct.unpack('>HHHHHH', q[:12])
    i = 12; labels = []
    while q[i] != 0:
        l = q[i]; labels.append(q[i+1:i+1+l].decode('latin1')); i += 1 + l
    i += 1
    qtype, qclass = struct.unpack('>HH', q[i:i+4])
    return dict(txid=txid, flags=flags, labels=labels, qname='.'.join(labels) + '.', qtype=qtype, qclass=qclass, qraw=q[12:i+4], ar=ar)
def rr(name, typ, ttl, rdata, cls=1):
    nm = enc_name(name) if isinstance(name, str) else name
    return nm + struct.pack('>HHIH', typ, cls, ttl, len(rdata)) + rdata
def ip4(s): return socket.inet_aton(s)
def ip6(s): return socket.inet_pton(socket.AF_INET6, s)
def cstr(s):
    b = s.encode() if isinstance(s, str) else s
    return bytes([len(b)]) + b
def pkt(Q, answers=(), auth=(), addl=(), rcode=0, flags=None, txid=None, qd=True):
    if flags is None: flags = 0x8180 | rcode
    t = Q['txid'] if txid is None else txid
    h = struct.pack('>HHHHHH', t, flags, 1 if qd else 0, len(answers), len(auth), len(addl))
    return h + (Q['qraw'] if qd else b'') + b''.join(answers) + b''.join(auth) + b''.join(addl)
def opt(size=1232, ext=0, ver=0, flags=0, data=b''):
    return b'\x00' + struct.pack('>HHBBHH', 41, size, ext, ver, flags, len(data)) + data

import os
def respond(q, proto):
    Q = parse_q(q)
    n = Q['qname']; t = Q['qtype']
    first = Q['labels'][0] if Q['labels'] else ''
    custom = '/tmp/t/custom.py'
    if os.path.exists(custom):
        g = dict(globals())
        exec(open(custom).read(), g)
        r = g['custom'](Q, proto)
        if r is not None: return r
    return pkt(Q, [rr(n, 1, 600, ip4('93.184.216.34'))])
EOF
