package uts46

import "unicode/utf8"

// Status is the UTS #46 status of a code point.
type Status int

const (
	Valid Status = iota
	Ignored
	Mapped
	Deviation
	Disallowed
	DisallowedStd3Valid
	DisallowedStd3Mapped
)

// Lookup returns the UTS #46 status of the rune, along with its mapping
// (only meaningful for Mapped, Deviation and DisallowedStd3Mapped).
func Lookup(r rune) (Status, string) {
	var buf [utf8.UTFMax]byte
	n := utf8.EncodeRune(buf[:], r)
	s := string(buf[:n])
	v, sz := trie.lookupString(s)
	if sz == 0 {
		return Disallowed, ""
	}
	c := info(v)
	switch c.category() {
	case valid, validNV8, validXV8:
		return Valid, ""
	case ignored:
		return Ignored, ""
	case mapped:
		return Mapped, string(c.appendMapping(nil, s))
	case deviation:
		return Deviation, string(c.appendMapping(nil, s))
	case disallowedSTD3Mapped:
		return DisallowedStd3Mapped, string(c.appendMapping(nil, s))
	case disallowedSTD3Valid:
		return DisallowedStd3Valid, ""
	default:
		return Disallowed, ""
	}
}
EOF
