package main

import (
	"fmt"
	"strings"
	"unicode/utf8"
)

// A minimal re-implementation of the semantics of a getopts-style parser.

type hasArg int

const (
	argNo hasArg = iota
	argYes
)

type occur int

const (
	occurOptional occur = iota
	occurMulti
)

type optDef struct {
	short string
	long  string
	arg   hasArg
	occ   occur
}

// name returns the primary name of the option: the long name if
// present, otherwise the short one.
func (o *optDef) name() string {
	if o.long != "" {
		return o.long
	}
	return o.short
}

type optVal struct {
	given bool
	val   string
	hasV  bool
}

type matches struct {
	defs []*optDef
	vals [][]optVal
	free []string
}

type getoptsError struct {
	msg string
}

func (e *getoptsError) Error() string { return e.msg }

func findOpt(defs []*optDef, nm string, isLong bool) int {
	for i, d := range defs {
		if isLong {
			if d.long != "" && d.long == nm {
				return i
			}
			if d.long == "" && d.short == nm {
				// Long-form lookups only match long names, but options
				// without a long name use their short name as the primary
				// name, so "--Z" would match "-Z".
				return i
			}
		} else {
			if d.short != "" && d.short == nm {
				return i
			}
			if d.short == "" && d.long == nm {
				return i
			}
		}
	}
	return -1
}

func isArg(s string) bool {
	return len(s) > 1 && s[0] == '-'
}

// rustDebugBytes formats a byte string the way Rust's Debug formats an
// OsStr containing invalid UTF-8.
func rustDebugOsStr(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for len(s) > 0 {
		r, size := utf8.DecodeRuneInString(s)
		if r == utf8.RuneError && size == 1 {
			fmt.Fprintf(&b, "\\x%02X", s[0])
			s = s[1:]
			continue
		}
		b.WriteString(escapeDebugChar(r))
		s = s[size:]
	}
	b.WriteByte('"')
	return b.String()
}

func getoptsParse(defs []*optDef, args []string) (*matches, error) {
	for _, a := range args {
		if !utf8.ValidString(a) {
			return nil, &getoptsError{fmt.Sprintf("Unrecognized option: '%s'", rustDebugOsStr(a))}
		}
	}

	m := &matches{defs: defs, vals: make([][]optVal, len(defs))}
	i := 0
	for i < len(args) {
		cur := args[i]
		i++
		if !isArg(cur) {
			m.free = append(m.free, cur)
			continue
		}
		if cur == "--" {
			m.free = append(m.free, args[i:]...)
			break
		}

		type nameT struct {
			nm     string
			isLong bool
		}
		var names []nameT
		var iArg *string

		if cur[1] == '-' {
			tail := cur[2:]
			parts := strings.SplitN(tail, "=", 2)
			names = []nameT{{parts[0], true}}
			if len(parts) == 2 {
				v := parts[1]
				iArg = &v
			}
		} else {
			rest := cur[1:]
			pos := 1
			for _, ch := range rest {
				nm := string(ch)
				id := findOpt(defs, nm, false)
				if id < 0 {
					return nil, &getoptsError{fmt.Sprintf("Unrecognized option: '%s'", nm)}
				}
				names = append(names, nameT{nm, false})
				next := pos + utf8.RuneLen(ch)
				if defs[id].arg == argYes {
					if next < len(cur) {
						v := cur[next:]
						iArg = &v
						break
					}
				}
				pos = next
			}
		}

		for ni, n := range names {
			id := findOpt(defs, n.nm, n.isLong)
			if id < 0 {
				return nil, &getoptsError{fmt.Sprintf("Unrecognized option: '%s'", n.nm)}
			}
			switch defs[id].arg {
			case argNo:
				if ni == len(names)-1 && iArg != nil {
					return nil, &getoptsError{fmt.Sprintf("Option '%s' does not take an argument", n.nm)}
				}
				m.vals[id] = append(m.vals[id], optVal{given: true})
			case argYes:
				if iArg != nil {
					m.vals[id] = append(m.vals[id], optVal{given: true, val: *iArg, hasV: true})
					iArg = nil
				} else if i < len(args) {
					m.vals[id] = append(m.vals[id], optVal{given: true, val: args[i], hasV: true})
					i++
				} else {
					return nil, &getoptsError{fmt.Sprintf("Argument to option '%s' missing", n.nm)}
				}
			}
		}
	}

	for id, d := range defs {
		if d.occ != occurMulti && len(m.vals[id]) > 1 {
			return nil, &getoptsError{fmt.Sprintf("Option '%s' given more than once", d.name())}
		}
	}
	return m, nil
}

func (m *matches) index(name string) int {
	for i, d := range m.defs {
		if d.long == name || (d.long == "" && d.short == name) || d.short == name {
			return i
		}
	}
	panic("no such option " + name)
}

func (m *matches) present(name string) bool {
	return len(m.vals[m.index(name)]) > 0
}

func (m *matches) str(name string) (string, bool) {
	for _, v := range m.vals[m.index(name)] {
		if v.hasV {
			return v.val, true
		}
	}
	return "", false
}

func (m *matches) strs(name string) []string {
	var out []string
	for _, v := range m.vals[m.index(name)] {
		if v.hasV {
			out = append(out, v.val)
		}
	}
	return out
}
EOF
echo done

