	{short: "J", long: "json", arg: argNo, occ: occurOptional},
	{short: "", long: "seconds", arg: argNo, occ: occurOptional},
	{short: "1", long: "short", arg: argNo, occ: occurOptional},
	{short: "v", long: "version", arg: argNo, occ: occurOptional},
	{short: "", long: "time", arg: argNo, occ: occurOptional},
	{short: "?", long: "help", arg: argNo, occ: occurOptional},
}

type UseColours int

const (
	ColoursAlways UseColours = iota
	ColoursAutomatic
	ColoursNever
)

func (u UseColours) debugName() string {
	switch u {
	case ColoursAlways:
		return "Always"
	case ColoursNever:
		return "Never"
	}
	return "Automatic"
}

func deduceColours(m *matches) UseColours {
	var w string
	var ok bool
	if w, ok = m.str("color"); !ok {
		w, ok = m.str("colour")
	}
	if !ok {
		return ColoursAutomatic
	}
	switch w {
	case "always", "yes":
		return ColoursAlways
	case "never", "no":
		return ColoursNever
	}
	return ColoursAutomatic
}

func (u UseColours) shouldUseColours() bool {
	switch u {
	case ColoursAlways:
		return true
	case ColoursNever:
		return false
	}
	if _, set := os.LookupEnv("NO_COLOR"); set {
		return false
	}
	return isTerminal(1)
}

type OutputKind int

const (
	FormatShort OutputKind = iota
	FormatJSON
	FormatText
)

type OutputFormat struct {
	kind            OutputKind
	colours         UseColours
	formatDurations bool
}

type TransportType int

const (
	TransportAutomatic TransportType = iota
	TransportUDP
	TransportTCP
	TransportTLS
	TransportHTTPS
)

func (t TransportType) debugName() string {
	switch t {
	case TransportUDP:
		return "UDP"
	case TransportTCP:
		return "TCP"
	case TransportTLS:
		return "TLS"
	case TransportHTTPS:
		return "HTTPS"
	}
	return "Automatic"
}

type ResolverType struct {
	systemDefault bool
	addr          string
}

type UseEDNS int

const (
	EDNSDisable UseEDNS = iota
	EDNSSendAndHide
	EDNSSendAndShow
)

func (e UseEDNS) debugName() string {
	switch e {
	case EDNSDisable:
		return "Disable"
	case EDNSSendAndShow:
		return "SendAndShow"
	}
	return "SendAndHide"
}

type ProtocolTweaks struct {
	setAuthoritative    bool
	setAuthentic        bool
	setCheckingDisabled bool
	udpPayloadSize      *uint16
}

type Inputs struct {
	domains        []Labels
	recordTypes    []QType
	classes        []QClass
	resolverTypes  []ResolverType
	transportTypes []TransportType
}

type RequestGenerator struct {
	inputs   Inputs
	txidSet  bool
	txid     uint16
	edns     UseEDNS
	tweaks   ProtocolTweaks
}

type Options struct {
	requests    RequestGenerator
	measureTime bool
	format      OutputFormat
}

type optionsResultKind int

const (
	resultOk optionsResultKind = iota
	resultHelpFlag
	resultHelpNoDomains
	resultVersion
	resultInvalid
)

type optionsResult struct {
	kind    optionsResultKind
	opts    *Options
	colours UseColours
	err     string
}

type optionsError struct{ msg string }

func (e *optionsError) Error() string { return e.msg }

func parseOptions(args []string) optionsResult {
	m, err := getoptsParse(optionDefs, args)
	if err != nil {
		return optionsResult{kind: resultInvalid, err: err.Error()}
	}
	uc := deduceColours(m)
	if m.present("version") {
		return optionsResult{kind: resultVersion, colours: uc}
	}
	if m.present("help") {
		return optionsResult{kind: resultHelpFlag, colours: uc}
	}
	opts, derr := deduceOptions(m)
	if derr != nil {
		return optionsResult{kind: resultInvalid, err: derr.Error()}
	}
	if len(opts.requests.inputs.domains) == 0 {
		return optionsResult{kind: resultHelpNoDomains, colours: uc}
	}
	return optionsResult{kind: resultOk, opts: opts, colours: uc}
}

func deduceOptions(m *matches) (*Options, error) {
	o := &Options{}
	o.measureTime = m.present("time")
	o.format = deduceOutputFormat(m)
	rg, err := deduceRequests(m)
	if err != nil {
		return nil, err
	}
	o.requests = *rg
	return o, nil
}

func deduceOutputFormat(m *matches) OutputFormat {
	fd := !m.present("seconds")
	if m.present("short") {
		return OutputFormat{kind: FormatShort, formatDurations: fd}
	}
	if m.present("json") {
		return OutputFormat{kind: FormatJSON}
	}
	return OutputFormat{kind: FormatText, colours: deduceColours(m), formatDurations: fd}
}

func deduceRequests(m *matches) (*RequestGenerator, error) {
	rg := &RequestGenerator{}

	// EDNS
	rg.edns = EDNSSendAndHide
	if e, ok := m.str("edns"); ok {
		switch e {
		case "disable", "off":
			rg.edns = EDNSDisable
		case "hide":
			rg.edns = EDNSSendAndHide
		case "show":
			rg.edns = EDNSSendAndShow
		default:
			return nil, &optionsError{fmt.Sprintf("Invalid EDNS setting %s", rustDebugStr(e))}
		}
	}

	// Transaction ID
	if t, ok := m.str("txid"); ok {
		n, ok := parseDecOrHex(t)
		if !ok {
			return nil, &optionsError{fmt.Sprintf("Invalid transaction ID %s", rustDebugStr(t))}
		}
		rg.txidSet = true
		rg.txid = n
	}

	// Protocol tweaks
	for _, tw := range m.strs("Z") {
		switch tw {
		case "aa", "authoritative":
			rg.tweaks.setAuthoritative = true
		case "ad", "authentic":
			rg.tweaks.setAuthentic = true
		case "cd", "checking-disabled":
			rg.tweaks.setCheckingDisabled = true
		default:
			if strings.HasPrefix(tw, "bufsize=") {
				if n, ok := parseRustU16(tw[len("bufsize="):], 10); ok {
					v := n
					rg.tweaks.udpPayloadSize = &v
					continue
				}
			}
			return nil, &optionsError{fmt.Sprintf("Invalid protocol tweak %s", rustDebugStr(tw))}
		}
	}

	inputs, err := deduceInputs(m)
	if err != nil {
		return nil, err
	}
	rg.inputs = *inputs
	return rg, nil
}

// parseRustU16 mimics Rust's u16::from_str_radix.
func parseRustU16(s string, radix int) (uint16, bool) {
	if s == "" {
		return 0, false
	}
	if s[0] == '+' {
		s = s[1:]
		if s == "" {
			return 0, false
		}
	}
	for _, c := range s {
		if c == '+' || c == '-' || c == '_' || c == ' ' {
			return 0, false
		}
	}
	n, err := strconv.ParseUint(s, radix, 16)
	if err != nil {
		return 0, false
	}
	return uint16(n), true
}

func parseDecOrHex(s string) (uint16, bool) {
	if strings.HasPrefix(s, "0x") {
		return parseRustU16(s[2:], 16)
	}
	return parseRustU16(s, 10)
}

func deduceInputs(m *matches) (*Inputs, error) {
	in := &Inputs{}

	// Transport types, in a fixed order.
	if m.present("https") {
		in.transportTypes = append(in.transportTypes, TransportHTTPS)
	}
	if m.present("tls") {
		in.transportTypes = append(in.transportTypes, TransportTLS)
	}
	if m.present("tcp") {
		in.transportTypes = append(in.transportTypes, TransportTCP)
	}
	if m.present("udp") {
		in.transportTypes = append(in.transportTypes, TransportUDP)
	}

	// Named arguments
	for _, d := range m.strs("query") {
		l, err := encodeLabels(d)
		if err != nil {
			return nil, &optionsError{fmt.Sprintf("Invalid domain %s", rustDebugStr(d))}
		}
		in.domains = append(in.domains, l)
	}
	for _, t := range m.strs("type") {
		if err := in.addType(t); err != nil {
			return nil, err
		}
	}
	for _, ns := range m.strs("nameserver") {
		in.addNameserver(ns)
	}
	for _, c := range m.strs("class") {
		cl, ok := parseClassName(c)
		if !ok {
			if n, ok2 := parseRustU16(c, 10); ok2 {
				cl = QClass(n)
			} else {
				return nil, &optionsError{fmt.Sprintf("Invalid query class %s", rustDebugStr(c))}
			}
		}
		in.classes = append(in.classes, cl)
	}

	// Free arguments
	for _, a := range m.free {
		if strings.HasPrefix(a, "@") {
			ns := a[1:]
			logTrace("dog::options", "Got nameserver -> %s", rustDebugStr(ns))
			in.addNameserver(ns)
		} else if isConstantName(a) {
			if strings.EqualFold(a, "OPT") {
				return nil, &optionsError{"OPT request is sent by default (see -Z flag)"}
			}
			if cl, ok := parseClassName(a); ok {
				logTrace("dog::options", "Got qclass -> %s", rustDebugStr(a))
				in.classes = append(in.classes, cl)
			} else if qt, ok := parseTypeName(a); ok {
				logTrace("dog::options", "Got qtype -> %s", rustDebugStr(a))
				in.recordTypes = append(in.recordTypes, qt)
			} else {
				logTrace("dog::options", "Got single-word domain -> %s", rustDebugStr(a))
				if err := in.addDomain(a); err != nil {
					return nil, err
				}
			}
		} else {
			logTrace("dog::options", "Got domain -> %s", rustDebugStr(a))
			if err := in.addDomain(a); err != nil {
				return nil, err
			}
		}
	}

	// Check for missing nameserver
	if len(in.resolverTypes) == 0 {
		for _, t := range in.transportTypes {
			if t == TransportHTTPS {
				return nil, &optionsError{"You must pass a URL as a nameserver when using --https"}
			}
		}
	}

	// Fallbacks
	if len(in.recordTypes) == 0 {
		in.recordTypes = append(in.recordTypes, QType(1))
	}
	if len(in.classes) == 0 {
		in.classes = append(in.classes, QClass(1))
	}
	if len(in.resolverTypes) == 0 {
		in.resolverTypes = append(in.resolverTypes, ResolverType{systemDefault: true})
	}
	if len(in.transportTypes) == 0 {
		in.transportTypes = append(in.transportTypes, TransportAutomatic)
	}
	return in, nil
}

func (in *Inputs) addType(t string) error {
	if strings.EqualFold(t, "OPT") {
		return &optionsError{"OPT request is sent by default (see -Z flag)"}
	}
	if qt, ok := parseTypeName(t); ok {
		in.recordTypes = append(in.recordTypes, qt)
		return nil
	}
	if n, ok := parseRustU16(t, 10); ok {
		in.recordTypes = append(in.recordTypes, QType(n))
		return nil
	}
	return &optionsError{fmt.Sprintf("Invalid query type %s", rustDebugStr(t))}
}

func (in *Inputs) addNameserver(ns string) {
	in.resolverTypes = append(in.resolverTypes, ResolverType{addr: ns})
}

func (in *Inputs) addDomain(d string) error {
	l, err := encodeLabels(d)
	if err != nil {
		return &optionsError{fmt.Sprintf("Invalid domain %s", rustDebugStr(d))}
	}
	in.domains = append(in.domains, l)
	return nil
}

func isConstantName(a string) bool {
	if a == "" {
		return false
	}
	c := a[0]
	if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')) {
		return false
	}
	for i := 0; i < len(a); i++ {
		c := a[i]
		if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9')) {
			return false
		}
	}
	return true
}

func parseClassName(s string) (QClass, bool) {
	switch strings.ToUpper(s) {
	case "IN":
		return QClass(1), true
	case "CH":
		return QClass(3), true
	case "HS":
		return QClass(4), true
	}
	return 0, false
}
