package main

import (
	"errors"
	"fmt"
	"strings"
	"unicode"
	"unicode/utf8"

	"dog/internal/bidi"
	"dog/internal/norm"
	"dog/internal/uts46"
)

type labelSegment struct {
	length uint8
	text   string
}

// Labels is a domain name as a sequence of labels.
type Labels struct {
	segments []labelSegment
}

func (l Labels) String() string {
	var b strings.Builder
	for _, s := range l.segments {
		b.WriteString(s.text)
		b.WriteByte('.')
	}
	return b.String()
}

func (l Labels) toWire() []byte {
	var out []byte
	for _, s := range l.segments {
		out = append(out, s.length)
		out = append(out, s.text...)
	}
	out = append(out, 0)
	return out
}

func encodeLabels(input string) (Labels, error) {
	var l Labels
	for _, label := range strings.Split(input, ".") {
		if label == "" {
			continue
		}
		ascii, errs := idnaToASCII(label)
		if len(errs) > 0 {
			logWarn("dns::strings", "Could not encode label %s: Errors([%s])", rustDebugStr(label), strings.Join(errs, ", "))
			return Labels{}, errors.New(label)
		}
		l.segments = append(l.segments, labelSegment{uint8(len(ascii)), ascii})
	}
	return l, nil
}

// ---- IDNA (UTS #46) processing ----

func isBidiRTL(r rune) bool {
	p, _ := bidi.LookupRune(r)
	c := p.Class()
	return c == bidi.R || c == bidi.AL || c == bidi.AN
}

func bidiClass(r rune) bidi.Class {
	p, _ := bidi.LookupRune(r)
	return p.Class()
}

func idnaToASCII(domain string) (string, []string) {
	var errs []string
	processed := idnaProcessing(domain, &errs)
	var result strings.Builder
	for i, label := range strings.Split(processed, ".") {
		if i > 0 {
			result.WriteByte('.')
		}
		if isASCII(label) {
			result.WriteString(label)
		} else {
			enc, ok := punycodeEncode(label)
			if !ok {
				errs = append(errs, "PunycodeError")
			} else {
				result.WriteString("xn--")
				result.WriteString(enc)
			}
		}
	}
	res := result.String()

	d := strings.TrimSuffix(res, ".")
	tooShort := len(d) < 1
	tooLong := len(d) > 253
	for _, lab := range strings.Split(d, ".") {
		if len(lab) < 1 {
			tooShort = true
		}
		if len(lab) > 63 {
			tooLong = true
		}
	}
	if tooShort {
		errs = append(errs, "TooShortForDns")
	}
	if tooLong {
		errs = append(errs, "TooLongForDns")
	}
	return res, errs
}

func isASCII(s string) bool {
	for i := 0; i < len(s); i++ {
		if s[i] >= 0x80 {
			return false
		}
	}
	return true
}

func idnaProcessing(domain string, errs *[]string) string {
	var mapped strings.Builder
	for _, c := range domain {
		st, m := uts46.Lookup(c)
		switch st {
		case uts46.Valid:
			mapped.WriteRune(c)
		case uts46.Ignored:
		case uts46.Mapped:
			mapped.WriteString(m)
		case uts46.Deviation:
			mapped.WriteRune(c)
		case uts46.Disallowed:
			*errs = append(*errs, "DissallowedCharacter")
			mapped.WriteRune(c)
		case uts46.DisallowedStd3Valid:
			mapped.WriteRune(c)
		case uts46.DisallowedStd3Mapped:
			mapped.WriteString(m)
		}
	}
	normalized := norm.NFC.String(mapped.String())

	isBidiDomain := false
	for _, c := range domain {
		if isBidiRTL(c) {
			isBidiDomain = true
			break
		}
	}
	if !isBidiDomain {
		for _, label := range strings.Split(normalized, ".") {
			if strings.HasPrefix(label, "xn--") {
				dec, ok := punycodeDecode(label[4:])
				if !ok {
					isBidiDomain = true
				} else {
					for _, c := range dec {
						if isBidiRTL(c) {
							isBidiDomain = true
						}
					}
				}
			}
		}
	}

	var validated strings.Builder
	for i, label := range strings.Split(normalized, ".") {
		if i > 0 {
			validated.WriteByte('.')
		}
		if strings.HasPrefix(label, "xn--") {
			dec, ok := punycodeDecode(label[4:])
			if ok {
				idnaValidate(dec, isBidiDomain, errs)
				validated.WriteString(dec)
			} else {
				*errs = append(*errs, "PunycodeError")
			}
		} else {
			idnaValidate(label, isBidiDomain, errs)
			validated.WriteString(label)
		}
	}
	return validated.String()
}

func idnaValidate(label string, isBidiDomain bool, errs *[]string) {
	if label == "" {
		return
	}
	first, _ := utf8.DecodeRuneInString(label)
	if strings.HasPrefix(label, "-") || strings.HasSuffix(label, "-") {
		*errs = append(*errs, "ValidityCriteria")
		return
	}
	if unicode.Is(unicode.M, first) {
		*errs = append(*errs, "ValidityCriteria")
		return
	}
	for _, c := range label {
		st, _ := uts46.Lookup(c)
		switch st {
		case uts46.Valid, uts46.Deviation, uts46.DisallowedStd3Valid:
		default:
			*errs = append(*errs, "ValidityCriteria")
			return
		}
	}
	if !passesBidi(label, isBidiDomain) {
		*errs = append(*errs, "ValidityCriteria")
	}
}

func passesBidi(label string, isBidiDomain bool) bool {
	if !isBidiDomain {
		return true
	}
	runes := []rune(label)
	if len(runes) == 0 {
		return true
	}
	firstClass := bidiClass(runes[0])
	switch firstClass {
	case bidi.L:
		for _, c := range runes[1:] {
			switch bidiClass(c) {
			case bidi.L, bidi.EN, bidi.ES, bidi.CS, bidi.ET, bidi.ON, bidi.BN, bidi.NSM:
			default:
				return false
			}
		}
		i := len(runes) - 1
		for i >= 0 && bidiClass(runes[i]) == bidi.NSM {
			i--
		}
		if i >= 0 {
			c := bidiClass(runes[i])
			if c != bidi.L && c != bidi.EN {
				return false
			}
		}
	case bidi.R, bidi.AL:
		foundEN, foundAN := false, false
		for _, c := range runes[1:] {
			cc := bidiClass(c)
			if cc == bidi.EN {
				foundEN = true
			} else if cc == bidi.AN {
				foundAN = true
			}
			switch cc {
			case bidi.R, bidi.AL, bidi.AN, bidi.EN, bidi.ES, bidi.CS, bidi.ET, bidi.ON, bidi.BN, bidi.NSM:
			default:
				return false
			}
		}
		i := len(runes) - 1
		for i >= 0 && bidiClass(runes[i]) == bidi.NSM {
			i--
		}
		if i < 0 {
			return false
		}
		switch bidiClass(runes[i]) {
		case bidi.R, bidi.AL, bidi.EN, bidi.AN:
		default:
			return false
		}
		if foundAN && foundEN {
			return false
		}
	default:
		return false
	}
	return true
}

// ---- Punycode (RFC 3492) ----

const (
	pcBase        = 36
	pcTMin        = 1
	pcTMax        = 26
	pcSkew        = 38
	pcDamp        = 700
	pcInitialBias = 72
	pcInitialN    = 128
)

func pcAdapt(delta, numPoints uint32, first bool) uint32 {
	if first {
		delta /= pcDamp
	} else {
		delta /= 2
	}
	delta += delta / numPoints
	k := uint32(0)
	for delta > ((pcBase-pcTMin)*pcTMax)/2 {
		delta /= pcBase - pcTMin
		k += pcBase
	}
	return k + (((pcBase - pcTMin + 1) * delta) / (delta + pcSkew))
}

func pcDigitValue(c byte) (uint32, bool) {
	switch {
	case c >= '0' && c <= '9':
		return uint32(c-'0') + 26, true
	case c >= 'A' && c <= 'Z':
		return uint32(c - 'A'), true
	case c >= 'a' && c <= 'z':
		return uint32(c - 'a'), true
	}
	return 0, false
}

func pcEncodeDigit(d uint32) byte {
	if d < 26 {
		return byte('a' + d)
	}
	return byte('0' + d - 26)
}

func punycodeDecode(input string) (string, bool) {
	var output []rune
	rest := input
	if idx := strings.LastIndexByte(input, '-'); idx >= 0 {
		for i := 0; i < idx; i++ {
			if input[i] >= 0x80 {
				return "", false
			}
			output = append(output, rune(input[i]))
		}
		rest = input[idx+1:]
	}
	n := uint32(pcInitialN)
	i := uint32(0)
	bias := uint32(pcInitialBias)
	pos := 0
	for pos < len(rest) {
		oldI := i
		w := uint32(1)
		for k := uint32(pcBase); ; k += pcBase {
			if pos >= len(rest) {
				return "", false
			}
			digit, ok := pcDigitValue(rest[pos])
			pos++
			if !ok {
				return "", false
			}
			if digit > (0xFFFFFFFF-i)/w {
				return "", false
			}
			i += digit * w
			var t uint32
			if k <= bias {
				t = pcTMin
			} else if k >= bias+pcTMax {
				t = pcTMax
			} else {
				t = k - bias
			}
			if digit < t {
				break
			}
			if w > 0xFFFFFFFF/(pcBase-t) {
				return "", false
			}
			w *= pcBase - t
		}
		length := uint32(len(output) + 1)
		bias = pcAdapt(i-oldI, length, oldI == 0)
		if i/length > 0xFFFFFFFF-n {
			return "", false
		}
		n += i / length
		i %= length
		if n > 0x10FFFF || (n >= 0xD800 && n <= 0xDFFF) {
			return "", false
		}
		output = append(output, 0)
		copy(output[i+1:], output[i:])
		output[i] = rune(n)
		i++
	}
	return string(output), true
}

func punycodeEncode(input string) (string, bool) {
	runes := []rune(input)
	var out []byte
	basic := 0
	for _, r := range runes {
		if r < 0x80 {
			out = append(out, byte(r))
			basic++
		}
	}
	if basic > 0 {
		out = append(out, '-')
	}
	n := uint32(pcInitialN)
	delta := uint32(0)
	bias := uint32(pcInitialBias)
	processed := uint32(basic)
	total := uint32(len(runes))
	for processed < total {
		m := uint32(0xFFFFFFFF)
		for _, r := range runes {
			if uint32(r) >= n && uint32(r) < m {
				m = uint32(r)
			}
		}
		if (m-n) > (0xFFFFFFFF-delta)/(processed+1) {
			return "", false
		}
		delta += (m - n) * (processed + 1)
		n = m
		for _, r := range runes {
			c := uint32(r)
			if c < n {
				delta++
				if delta == 0 {
					return "", false
				}
			}
			if c == n {
				q := delta
				for k := uint32(pcBase); ; k += pcBase {
					var t uint32
					if k <= bias {
						t = pcTMin
					} else if k >= bias+pcTMax {
						t = pcTMax
					} else {
						t = k - bias
					}
					if q < t {
						break
					}
					out = append(out, pcEncodeDigit(t+(q-t)%(pcBase-t)))
					q = (q - t) / (pcBase - t)
				}
				out = append(out, pcEncodeDigit(q))
				bias = pcAdapt(delta, processed+1, processed == uint32(basic))
				delta = 0
				processed++
			}
		}
		delta++
		n++
	}
	return string(out), true
}

// ---- Rust-style Debug string escaping ----

func isGraphemeExtend(r rune) bool {
	return unicode.Is(unicode.Mn, r) || unicode.Is(unicode.Me, r) || unicode.Is(unicode.Other_Grapheme_Extend, r)
}

func isPrintableRust(r rune) bool {
	if r < 0x20 {
		return false
	}
	if r < 0x7f {
		return true
	}
	if r == 0x7f {
		return false
	}
	if unicode.Is(unicode.Cc, r) || unicode.Is(unicode.Cf, r) || unicode.Is(unicode.Cs, r) ||
		unicode.Is(unicode.Co, r) || unicode.Is(unicode.Zl, r) || unicode.Is(unicode.Zp, r) {
		return false
	}
	if unicode.Is(unicode.Zs, r) && r != ' ' {
		return false
	}
	// Unassigned code points
	if !(unicode.Is(unicode.L, r) || unicode.Is(unicode.M, r) || unicode.Is(unicode.N, r) ||
		unicode.Is(unicode.P, r) || unicode.Is(unicode.S, r) || unicode.Is(unicode.Z, r) || unicode.Is(unicode.C, r)) {
		return false
	}
	return true
}

func escapeDebugChar(r rune) string {
	switch r {
	case 0:
		return "\\0"
	case '\t':
		return "\\t"
	case '\r':
		return "\\r"
	case '\n':
		return "\\n"
	case '\\':
		return "\\\\"
	case '"':
		return "\\\""
	}
	if isGraphemeExtend(r) || !isPrintableRust(r) {
		return fmt.Sprintf("\\u{%x}", r)
	}
	return string(r)
}

// rustDebugStr formats a string the way Rust's {:?} does.
func rustDebugStr(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for _, r := range s {
		b.WriteString(escapeDebugChar(r))
	}
	b.WriteByte('"')
	return b.String()
}
