	case wireExactLength:
		return fmt.Sprintf("Malformed packet: record length should be %d, got %d", e.expected, e.stated)
	case wireAtLeastLength:
		return fmt.Sprintf("Malformed packet: record length should be at least %d, got %d", e.expected, e.stated)
	case wireLabelLength:
		return fmt.Sprintf("Malformed packet: length %d was specified, but read %d bytes", e.stated, e.read)
	case wireRecursion:
