	case wireVersion:
		return fmt.Sprintf("Malformed packet: record specifies version %d, expected up to %d", e.stated, e.expected)
	}
	return "Malformed packet"
}

var errIO = &WireError{kind: wireIO}

// ---- Cursor ----

type cursor struct {
	buf []byte
	pos int
}

func (c *cursor) u8() (uint8, error) {
	if c.pos >= len(c.buf) {
		return 0, errIO
	}
	b := c.buf[c.pos]
	c.pos++
	return b, nil
}

func (c *cursor) u16() (uint16, error) {
	if c.pos+2 > len(c.buf) {
		c.pos = len(c.buf)
		return 0, errIO
	}
	v := binary.BigEndian.Uint16(c.buf[c.pos:])
	c.pos += 2
	return v, nil
}

func (c *cursor) u32() (uint32, error) {
	if c.pos+4 > len(c.buf) {
		c.pos = len(c.buf)
		return 0, errIO
	}
	v := binary.BigEndian.Uint32(c.buf[c.pos:])
	c.pos += 4
	return v, nil
}

func (c *cursor) bytes(n int) ([]byte, error) {
	if n < 0 || c.pos+n > len(c.buf) || c.pos > len(c.buf) {
		c.pos = len(c.buf)
		return nil, errIO
	}
	b := make([]byte, n)
	copy(b, c.buf[c.pos:c.pos+n])
	c.pos += n
	return b, nil
}

const recursionLimit = 8

// readLabels reads a (possibly compressed) domain name, returning the
// labels and the number of bytes consumed at the current position.
func (c *cursor) readLabels() (Labels, int, error) {
	var l Labels
	var recursions []uint16
	n, err := c.readLabelsRec(&l, &recursions)
	return l, n, err
}

func (c *cursor) readLabelsRec(l *Labels, recursions *[]uint16) (int, error) {
	bytesRead := 0
	for {
		b, err := c.u8()
		if err != nil {
			return bytesRead, err
		}
		bytesRead++
		if b == 0 {
			break
		} else if b >= 0xC0 {
			b2, err := c.u8()
			if err != nil {
				return bytesRead, err
			}
			bytesRead++
			offset := uint16(b-0xC0)<<8 | uint16(b2)
			for _, r := range *recursions {
				if r == offset {
					logWarn("dns::strings", "Hit previous offset (%d) decoding string", offset)
					return bytesRead, &WireError{kind: wireRecursion, indices: append([]uint16(nil), (*recursions)...)}
				}
			}
			*recursions = append(*recursions, offset)
			if len(*recursions) >= recursionLimit {
				logWarn("dns::strings", "Hit recursion limit (%d) decoding string", recursionLimit)
				return bytesRead, &WireError{kind: wireRecursion, indices: append([]uint16(nil), (*recursions)...)}
			}
			logTrace("dns::strings", "Backtracking to offset %d", offset)
			newPos := c.pos
			c.pos = int(offset)
			if _, err := c.readLabelsRec(l, recursions); err != nil {
				return bytesRead, err
			}
			logTrace("dns::strings", "Coming back to %d", newPos)
			c.pos = newPos
			break
		} else {
			buf := make([]byte, 0, b)
			for i := 0; i < int(b); i++ {
				x, err := c.u8()
				if err != nil {
					return bytesRead, err
				}
				bytesRead++
				buf = append(buf, x)
			}
			l.segments = append(l.segments, labelSegment{b, rustLossy(buf)})
		}
	}
	return bytesRead, nil
}

// rustLossy converts bytes to a string the way Rust's
// String::from_utf8_lossy does.
func rustLossy(src []byte) string {
	var out strings.Builder
	get := func(i int) byte {
		if i < len(src) {
			return src[i]
		}
		return 0
	}
	isCont := func(b byte) bool { return b >= 0x80 && b <= 0xBF }
	i := 0
	for i < len(src) {
		start := i
		b := src[i]
		i++
		if b < 0x80 {
			out.WriteByte(b)
			continue
		}
		ok := false
		switch {
		case b >= 0xC2 && b <= 0xDF:
			if isCont(get(i)) {
				i++
				ok = true
			}
		case b >= 0xE0 && b <= 0xEF:
			b1 := get(i)
			good := false
			switch {
			case b == 0xE0 && b1 >= 0xA0 && b1 <= 0xBF:
				good = true
			case b >= 0xE1 && b <= 0xEC && isCont(b1):
				good = true
			case b == 0xED && b1 >= 0x80 && b1 <= 0x9F:
				good = true
			case b >= 0xEE && b <= 0xEF && isCont(b1):
				good = true
			}
			if good {
				i++
				if isCont(get(i)) {
					i++
					ok = true
				}
			}
		case b >= 0xF0 && b <= 0xF4:
			b1 := get(i)
			good := false
			switch {
			case b == 0xF0 && b1 >= 0x90 && b1 <= 0xBF:
				good = true
			case b >= 0xF1 && b <= 0xF3 && isCont(b1):
				good = true
			case b == 0xF4 && b1 >= 0x80 && b1 <= 0x8F:
				good = true
			}
			if good {
				i++
				if isCont(get(i)) {
					i++
					if isCont(get(i)) {
						i++
						ok = true
					}
				}
			}
		}
		if ok {
			out.Write(src[start:i])
		} else {
			out.WriteString("\uFFFD")
		}
	}
	return out.String()
}

// ---- Requests ----

type Request struct {
	txid    uint16
	flags   uint16
	name    Labels
	qtype   QType
	qclass  QClass
	edns    bool
	udpSize uint16
}

func (r *Request) toWire() []byte {
	var out []byte
	out = binary.BigEndian.AppendUint16(out, r.txid)
	out = binary.BigEndian.AppendUint16(out, r.flags)
	out = binary.BigEndian.AppendUint16(out, 1)
	out = binary.BigEndian.AppendUint16(out, 0)
	out = binary.BigEndian.AppendUint16(out, 0)
	if r.edns {
		out = binary.BigEndian.AppendUint16(out, 1)
	} else {
		out = binary.BigEndian.AppendUint16(out, 0)
	}
	out = append(out, r.name.toWire()...)
	out = binary.BigEndian.AppendUint16(out, uint16(r.qtype))
	out = binary.BigEndian.AppendUint16(out, uint16(r.qclass))
	if r.edns {
		out = append(out, 0)
		out = binary.BigEndian.AppendUint16(out, 41)
		out = binary.BigEndian.AppendUint16(out, r.udpSize)
		out = append(out, 0, 0)
		out = binary.BigEndian.AppendUint16(out, 0)
		out = binary.BigEndian.AppendUint16(out, 0)
	}
	return out
}

// ---- Responses ----

type Flags struct {
	response           bool
	opcode             uint8
	authoritative      bool
	truncated          bool
	recursionDesired   bool
	recursionAvailable bool
	authenticData      bool
	checkingDisabled   bool
	rcode              uint8
}

func flagsFromU16(v uint16) Flags {
	return Flags{
		response:           v&0x8000 != 0,
		opcode:             uint8((v >> 11) & 0xF),
		authoritative:      v&0x0400 != 0,
		truncated:          v&0x0200 != 0,
		recursionDesired:   v&0x0100 != 0,
		recursionAvailable: v&0x0080 != 0,
		authenticData:      v&0x0020 != 0,
		checkingDisabled:   v&0x0010 != 0,
		rcode:              uint8(v & 0xF),
	}
}

func (f Flags) debugString() string {
	b := func(x bool) string {
		if x {
			return "true"
		}
		return "false"
	}
	op := "Query"
	if f.opcode != 0 {
		op = fmt.Sprintf("Other(\n        %d,\n    )", f.opcode)
	}
	ec := "None"
	if f.rcode != 0 {
		ec = "Some(\n        " + rcodeDebug(f.rcode) + ",\n    )"
	}
	return "Flags {\n" +
		"    response: " + b(f.response) + ",\n" +
		"    opcode: " + op + ",\n" +
		"    authoritative: " + b(f.authoritative) + ",\n" +
		"    truncated: " + b(f.truncated) + ",\n" +
		"    recursion_desired: " + b(f.recursionDesired) + ",\n" +
		"    recursion_available: " + b(f.recursionAvailable) + ",\n" +
		"    authentic_data: " + b(f.authenticData) + ",\n" +
		"    checking_disabled: " + b(f.checkingDisabled) + ",\n" +
		"    error_code: " + ec + ",\n" +
		"}"
}

func rcodeDebug(r uint8) string {
	switch r {
	case 1:
		return "FormatError"
	case 2:
		return "ServerFailure"
	case 3:
		return "NXDomain"
	case 4:
		return "NotImplemented"
	case 5:
		return "QueryRefused"
	}
	return fmt.Sprintf("Other(\n            %d,\n        )", r)
}

type Query struct {
	qname  Labels
	qtype  uint16
	qclass uint16
}

type Answer struct {
	pseudo bool
	qname  Labels
	// standard
	qclass uint16
	ttl    uint32
	record Record
	// pseudo
	opt OPTRecord
}

type OPTRecord struct {
	udpPayloadSize uint16
	higherBits     uint8
	ednsVersion    uint8
	flags          uint16
	data           []byte
}

type Response struct {
	txid        uint16
	flags       Flags
	queries     []Query
	answers     []Answer
	authorities []Answer
	additionals []Answer
}

func parseResponse(buf []byte) (*Response, error) {
	logInfo("dns::wire", "Parsing response")
	logTraceLazy("dns::wire", func() string { return "Bytes -> " + debugByteList(buf) })
	c := &cursor{buf: buf}
	r := &Response{}
	var err error
	if r.txid, err = c.u16(); err != nil {
		return nil, err
	}
	logTrace("dns::wire", "Read txid -> %d", r.txid)
	fl, err := c.u16()
	if err != nil {
		return nil, err
	}
	r.flags = flagsFromU16(fl)
	logTraceLazy("dns::wire", func() string { return "Read flags -> " + r.flags.debugString() })
	qd, err := c.u16()
	if err != nil {
		return nil, err
	}
	an, err := c.u16()
	if err != nil {
		return nil, err
	}
	ns, err := c.u16()
	if err != nil {
		return nil, err
	}
	ar, err := c.u16()
	if err != nil {
		return nil, err
	}

	logDebug("dns::wire", "Reading %dx query from response", qd)
	for i := 0; i < int(qd); i++ {
		name, _, err := c.readLabels()
		if err != nil {
			return nil, err
		}
		qt, err := c.u16()
		if err != nil {
			return nil, err
		}
		logTrace("dns::wire", "Read qtype number -> %d", qt)
		logTrace("dns::wire", "Found qtype -> %s", typeDebugShort(qt))
		qc, err := c.u16()
		if err != nil {
			return nil, err
		}
		logTrace("dns::wire", "Read qclass -> %s", typeDebugShort(qt))
		r.queries = append(r.queries, Query{name, qt, qc})
	}

	readAnswers := func(n uint16) ([]Answer, error) {
		var out []Answer
		for i := 0; i < int(n); i++ {
			name, _, err := c.readLabels()
			if err != nil {
				return nil, err
			}
			a, err := readAnswer(name, c)
			if err != nil {
				return nil, err
			}
			out = append(out, a)
		}
		return out, nil
	}

	logDebug("dns::wire", "Reading %dx answer from response", an)
	if r.answers, err = readAnswers(an); err != nil {
		return nil, err
	}
	logDebug("dns::wire", "Reading %dx authority from response", ns)
	if r.authorities, err = readAnswers(ns); err != nil {
		return nil, err
	}
	logDebug("dns::wire", "Reading %dx additional answer from response", ar)
	if r.additionals, err = readAnswers(ar); err != nil {
		return nil, err
	}
	return r, nil
}

func typeDebugShort(n uint16) string {
	if s, ok := knownTypeName(n); ok {
		return s
	}
	if n == 41 {
		return "OPT"
	}
	if s, ok := heardOfTypeName(n); ok {
		return fmt.Sprintf("Other(HeardOf(%s, %d))", rustDebugStr(s), n)
	}
	return fmt.Sprintf("Other(UnheardOf(%d))", n)
}

func debugByteList(b []byte) string {
	parts := make([]string, len(b))
	for i, x := range b {
		parts[i] = fmt.Sprint(x)
	}
	return "[" + strings.Join(parts, ", ") + "]"
}

func readAnswer(name Labels, c *cursor) (Answer, error) {
	qt, err := c.u16()
	if err != nil {
		return Answer{}, err
	}
	logTrace("dns::wire", "Read qtype number -> %d", qt)
	if qt == 41 {
		opt, err := readOPT(c)
		if err != nil {
			return Answer{}, err
		}
		return Answer{pseudo: true, qname: name, opt: opt}, nil
	}
	logTrace("dns::wire", "Found qtype -> %s", typeDebugShort(qt))
	qc, err := c.u16()
	if err != nil {
		return Answer{}, err
	}
	logTrace("dns::wire", "Read qclass -> %s", typeDebugShort(qt))
	ttl, err := c.u32()
	if err != nil {
		return Answer{}, err
	}
	logTrace("dns::wire", "Read TTL -> %d", ttl)
	rl, err := c.u16()
	if err != nil {
		return Answer{}, err
	}
	logTrace("dns::wire", "Read record length -> %d", rl)
	rec, err := readRecord(qt, rl, c)
	if err != nil {
		return Answer{}, err
	}
	return Answer{qname: name, qclass: qc, ttl: ttl, record: rec}, nil
}

func readOPT(c *cursor) (OPTRecord, error) {
	var o OPTRecord
	var err error
	if o.udpPayloadSize, err = c.u16(); err != nil {
		return o, err
	}
	if o.higherBits, err = c.u8(); err != nil {
		return o, err
	}
	if o.ednsVersion, err = c.u8(); err != nil {
		return o, err
	}
	if o.flags, err = c.u16(); err != nil {
		return o, err
	}
	dl, err := c.u16()
	if err != nil {
		return o, err
	}
	if o.data, err = c.bytes(int(dl)); err != nil {
		return o, err
	}
	return o, nil
}
EOF
