		}
		if l <= 3 {
			return nil, &WireError{kind: wireAtLeastLength, stated: int(l), expected: 4}
		}
		if r.data, err = c.bytes(int(l) - 3); err != nil {
			return nil, err
		}
		return r, nil
	case 16:
		var r recTXT
		var buf []byte
		total := 0
		for {
			n, err := c.u8()
			if err != nil {
				return nil, err
			}
			total++
			b, err := c.bytes(int(n))
			if err != nil {
				return nil, err
			}
			total += int(n)
			buf = append(buf, b...)
			if n != 255 {
				r.messages = append(r.messages, buf)
				buf = nil
			}
			if total >= int(l) {
				break
			}
		}
		if buf != nil {
			r.messages = append(r.messages, buf)
		}
		if err := labelLenCheck(l, total); err != nil {
			return nil, err
		}
		return r, nil
	case 256:
		var r recURI
		var err error
		if r.priority, err = c.u16(); err != nil {
			return nil, err
		}
		if r.weight, err = c.u16(); err != nil {
			return nil, err
		}
		if l <= 4 {
			return nil, &WireError{kind: wireAtLeastLength, stated: int(l), expected: 5}
		}
		if r.target, err = c.bytes(int(l) - 4); err != nil {
			return nil, err
		}
		return r, nil
	}
	b, err := c.bytes(int(l))
	if err != nil {
		return nil, err
	}
	return recOther{t, b}, nil
}

// ---- Formatting helpers ----

func formatIPv4(a [4]byte) string {
	return fmt.Sprintf("%d.%d.%d.%d", a[0], a[1], a[2], a[3])
}

func formatIPv6(a [16]byte) string {
	var seg [8]uint16
	for i := 0; i < 8; i++ {
		seg[i] = uint16(a[2*i])<<8 | uint16(a[2*i+1])
	}
	if seg[0] == 0 && seg[1] == 0 && seg[2] == 0 && seg[3] == 0 && seg[4] == 0 && seg[5] == 0xffff {
		return fmt.Sprintf("::ffff:%d.%d.%d.%d", a[12], a[13], a[14], a[15])
	}
	bestStart, bestLen := 0, 0
	curStart, curLen := 0, 0
	for i, s := range seg {
		if s == 0 {
			if curLen == 0 {
				curStart = i
			}
			curLen++
			if curLen > bestLen {
				bestStart, bestLen = curStart, curLen
			}
		} else {
			curLen = 0
		}
	}
	join := func(ss []uint16) string {
		parts := make([]string, len(ss))
		for i, s := range ss {
			parts[i] = fmt.Sprintf("%x", s)
		}
		return strings.Join(parts, ":")
	}
	if bestLen > 1 {
		return join(seg[:bestStart]) + "::" + join(seg[bestStart+bestLen:])
	}
	return join(seg[:])
}

var _ = netip.Addr{}

// asciiEscape formats bytes as a quoted string, escaping unprintable
// bytes as decimal escapes.
func asciiEscape(b []byte) string {
	var s strings.Builder
	s.WriteByte('"')
	for _, c := range b {
		switch {
		case c == '"':
			s.WriteString("\\\"")
		case c == '\\':
			s.WriteString("\\\\")
		case c < 32 || c >= 128:
			fmt.Fprintf(&s, "\\%d", c)
		default:
			s.WriteByte(c)
		}
	}
	s.WriteByte('"')
	return s.String()
}

func formatDuration(secs uint32) string {
	s := uint64(secs)
	if s < 60 {
		return fmt.Sprintf("%ds", s)
	}
	if s < 3600 {
		return fmt.Sprintf("%dm%02ds", s/60, s%60)
	}
	if s < 86400 {
		return fmt.Sprintf("%dh%02dm%02ds", s/3600, (s%3600)/60, s%60)
	}
	return fmt.Sprintf("%dd%dh%02dm%02ds", s/86400, (s%86400)/3600, (s%3600)/60, s%60)
}

func (tf textFormat) duration(secs uint32) string {
	if tf.formatDurations {
		return formatDuration(secs)
	}
	return fmt.Sprint(secs)
}

type textFormat struct {
	formatDurations bool
}

func euiFormat(b []byte) string {
	parts := make([]string, len(b))
	for i, x := range b {
		parts[i] = fmt.Sprintf("%02x", x)
	}
	return strings.Join(parts, "-")
}

func locSize(b byte) string {
	return fmt.Sprintf("%de%d", b>>4, b&0x0F)
}

func locPosition(raw uint32, isLat bool) (string, bool) {
	v := int64(raw) - (1 << 31)
	limit := int64(324000000)
	if !isLat {
		limit = 648000000
	}
	if v > limit || v < -limit {
		return "", false
	}
	var dir string
	if isLat {
		if v >= 0 {
			dir = "N"
		} else {
			dir = "S"
		}
	} else {
		if v >= 0 {
			dir = "E"
		} else {
			dir = "W"
		}
	}
	if v < 0 {
		v = -v
	}
	deg := v / 3600000
	min := (v % 3600000) / 60000
	sec := (v % 60000) / 1000
	ms := v % 1000
	secStr := fmt.Sprint(sec)
	if ms != 0 {
		secStr = fmt.Sprintf("%d.%03d", sec, ms)
	}
	return fmt.Sprintf("%d°%d′%s″ %s", deg, min, secStr, dir), true
}

func locAltitude(raw uint32) string {
	v := int64(raw) - 10000000
	m := v / 100
	cm := v % 100
	if cm == 0 {
		return fmt.Sprintf("%dm", m)
	}
	return fmt.Sprintf("%d.%sm", m, rustPad2(cm))
}

// rustPad2 formats a signed integer like Rust's {:02}.
func rustPad2(n int64) string {
	if n < 0 {
		s := fmt.Sprint(n)
		if len(s) < 2 {
			return s
		}
		return s
	}
	return fmt.Sprintf("%02d", n)
}

func (tf textFormat) recordSummary(r Record) string {
	switch r := r.(type) {
	case recA:
		return formatIPv4(r.addr)
	case recAAAA:
		return formatIPv6(r.addr)
	case recCAA:
		if r.critical {
			return fmt.Sprintf("%s %s (critical)", asciiEscape(r.tag), asciiEscape(r.value))
		}
		return fmt.Sprintf("%s %s (non-critical)", asciiEscape(r.tag), asciiEscape(r.value))
	case recCNAME:
		return rustDebugStr(r.domain.String())
	case recEUI48:
		return rustDebugStr(euiFormat(r.octets))
	case recEUI64:
		return rustDebugStr(euiFormat(r.octets))
	case recHINFO:
		return fmt.Sprintf("%s %s", asciiEscape(r.cpu), asciiEscape(r.os))
	case recLOC:
		lat, ok1 := locPosition(r.lat, true)
		if !ok1 {
			lat = "Out of range"
		}
		lon, ok2 := locPosition(r.lon, false)
		if !ok2 {
			lon = "Out of range"
		}
		return fmt.Sprintf("%s (%d, %d) (%s, %s, %s)", locSize(r.size), r.horiz, r.vert, lat, lon, locAltitude(r.alt))
	case recMX:
		return fmt.Sprintf("%d %s", r.preference, rustDebugStr(r.exchange.String()))
	case recNAPTR:
		return fmt.Sprintf("%d %d %s %s %s %s", r.order, r.preference, asciiEscape(r.flags), asciiEscape(r.service), asciiEscape(r.regex), rustDebugStr(r.replacement.String()))
	case recNS:
		return rustDebugStr(r.nameserver.String())
	case recOPENPGPKEY:
		return rustDebugStr(base64.StdEncoding.EncodeToString(r.key))
	case recPTR:
		return rustDebugStr(r.cname.String())
	case recSSHFP:
		return fmt.Sprintf("%d %d %s", r.algorithm, r.fpType, hex.EncodeToString(r.fingerprint))
	case recSOA:
		return fmt.Sprintf("%s %s %d %s %s %s %s", rustDebugStr(r.mname.String()), rustDebugStr(r.rname.String()), r.serial,
			tf.duration(r.refresh), tf.duration(r.retry), tf.duration(r.expire), tf.duration(r.minimum))
	case recSRV:
		return fmt.Sprintf("%d %d %s:%d", r.priority, r.weight, rustDebugStr(r.target.String()), r.port)
	case recTLSA:
		return fmt.Sprintf("%d %d %d %s", r.usage, r.selector, r.matching, rustDebugStr(hex.EncodeToString(r.data)))
	case recTXT:
		parts := make([]string, len(r.messages))
		for i, m := range r.messages {
			parts[i] = asciiEscape(m)
		}
		return strings.Join(parts, ", ")
	case recURI:
		return fmt.Sprintf("%d %d %s", r.priority, r.weight, asciiEscape(r.target))
	case recOther:
		return debugByteList(r.bytes)
	}
	return ""
}

func (tf textFormat) pseudoSummary(o OPTRecord) string {
	return fmt.Sprintf("%d %d %d %d %s", o.udpPayloadSize, o.higherBits, o.ednsVersion, o.flags, debugByteList(o.data))
}
EOF
echo ok"}

