func (recEUI64) typeNum() uint16      { return 109 }
func (recHINFO) typeNum() uint16      { return 13 }
func (recLOC) typeNum() uint16        { return 29 }
func (recMX) typeNum() uint16         { return 15 }
func (recNAPTR) typeNum() uint16      { return 35 }
func (recNS) typeNum() uint16         { return 2 }
func (recOPENPGPKEY) typeNum() uint16 { return 61 }
func (recPTR) typeNum() uint16        { return 12 }
func (recSSHFP) typeNum() uint16      { return 44 }
func (recSOA) typeNum() uint16        { return 6 }
func (recSRV) typeNum() uint16        { return 33 }
func (recTLSA) typeNum() uint16       { return 52 }
func (recTXT) typeNum() uint16        { return 16 }
