	if int(stated) != n {
		return &WireError{kind: wireExactLength, stated: int(stated), expected: n}
	}
	return nil
}

func labelLenCheck(stated uint16, read int) error {
	if int(stated) != read {
		return &WireError{kind: wireLabelLength, stated: int(stated), read: read}
	}
	return nil
}

func readCString(c *cursor) ([]byte, error) {
	n, err := c.u8()
	if err != nil {
		return nil, err
	}
	return c.bytes(int(n))
}

func readRecord(t uint16, l uint16, c *cursor) (Record, error) {
	if name, ok := knownTypeName(t); ok {
