	}
	switch t {
	case 1:
		if l != 4 {
			logWarn("dns::record::a", "Length is incorrect (record length %d, but should be four)", l)
			return nil, exactLen(l, 4)
		}
		b, err := c.bytes(4)
		if err != nil {
			return nil, err
		}
		var r recA
		copy(r.addr[:], b)
		logTrace("dns::record::a", "Parsed IPv4 address -> %s", formatIPv4(r.addr))
