	case 28:
		if l != 16 {
			logWarn("dns::record::aaaa", "Length is incorrect (record length %d, but should be sixteen)", l)
			return nil, exactLen(l, 16)
		}
		b, err := c.bytes(16)
		if err != nil {
			return nil, err
		}
