	case 108:
		if l != 6 {
			return nil, exactLen(l, 6)
		}
		b, err := c.bytes(6)
		if err != nil {
			return nil, err
		}
		return recEUI48{b}, nil
	case 109:
		if l != 8 {
			return nil, exactLen(l, 8)
		}
		b, err := c.bytes(8)
		if err != nil {
			return nil, err
		}
		return recEUI64{b}, nil
	case 13:
		cpu, err := readCString(c)
		if err != nil {
			return nil, err
		}
		os, err := readCString(c)
		if err != nil {
			return nil, err
		}
		if err := labelLenCheck(l, len(cpu)+len(os)+2); err != nil {
			return nil, err
		}
		return recHINFO{cpu, os}, nil
	case 29:
		ver, err := c.u8()
