		}
		if l != 16 {
			return nil, exactLen(l, 16)
		}
		var r recLOC
		if r.size, err = c.u8(); err != nil {
			return nil, err
		}
		if r.horiz, err = c.u8(); err != nil {
			return nil, err
		}
		if r.vert, err = c.u8(); err != nil {
			return nil, err
		}
		if r.lat, err = c.u32(); err != nil {
			return nil, err
		}
		if r.lon, err = c.u32(); err != nil {
			return nil, err
		}
		if r.alt, err = c.u32(); err != nil {
			return nil, err
		}
		return r, nil
	case 15:
		pref, err := c.u16()
		if err != nil {
			return nil, err
		}
		name, n, err := c.readLabels()
		if err != nil {
			return nil, err
		}
