		return recNS{name}, nil
	case 61:
		if l == 0 {
			return nil, &WireError{kind: wireAtLeastLength, stated: int(l), expected: 1}
		}
		b, err := c.bytes(int(l))
		if err != nil {
			return nil, err
		}
		return recOPENPGPKEY{b}, nil
	case 12:
		name, n, err := c.readLabels()
		if err != nil {
			return nil, err
		}
		if err := labelLenCheck(l, n); err != nil {
			return nil, err
