package main

import (
	"bufio"
	"encoding/base64"
	"encoding/hex"
	"fmt"
	"os"
	"strconv"
	"strings"
	"time"
)

var stdout = bufio.NewWriterSize(os.Stdout, 8192)

// ---- ANSI styles ----

type style string

func (s style) paint(text string) string {
	if s == "" {
		return text
	}
	return "\x1b[" + string(s) + "m" + text + "\x1b[0m"
}

type palette struct {
	qname, answer, authority, additional style
	enabled                               bool
}

func newPalette(colour bool) palette {
	if !colour {
		return palette{}
	}
	return palette{qname: "1;34", answer: "", authority: "36", additional: "32", enabled: true}
}

func (p palette) typeStyle(t uint16, pseudo bool) style {
	if !p.enabled {
		return ""
	}
	if pseudo {
		return "35"
	}
	switch t {
	case 1, 28:
		return "1;32"
	case 257, 2, 12, 35:
		return "31"
	case 5, 108, 13, 29, 52, 16, 256:
		return "33"
	case 109:
		return "1;33"
	case 15, 61, 44, 33:
		return "36"
	case 6:
		return "35"
	}
	return "41;37"
}

// ---- Text table ----

type section int

const (
	sectionAnswer section = iota
	sectionAuthority
	sectionAdditional
)

type tableRow struct {
	qtype      string
	qtypeLen   int
	qname      string
	ttl        *string
	section    section
	summary    string
}

type table struct {
	pal  palette
	tf   textFormat
	rows []tableRow
}

func (t *table) addRow(a Answer, s section) {
	if a.pseudo {
		t.rows = append(t.rows, tableRow{
			qtype:    t.pal.typeStyle(41, true).paint("OPT"),
			qtypeLen: 3,
			qname:    a.qname.String(),
			section:  s,
			summary:  t.tf.pseudoSummary(a.opt),
		})
		return
	}
	n := a.record.typeNum()
	name := recordTypeName(a.record)
	ttl := t.tf.duration(a.ttl)
	t.rows = append(t.rows, tableRow{
		qtype:    t.pal.typeStyle(n, false).paint(name),
		qtypeLen: len(name),
		qname:    a.qname.String(),
		ttl:      &ttl,
		section:  s,
		summary:  t.tf.recordSummary(a.record),
	})
}

func recordTypeName(r Record) string {
	if o, ok := r.(recOther); ok {
		if s, ok := heardOfTypeName(o.num); ok {
			return s
		}
		return strconv.Itoa(int(o.num))
	}
	s, _ := knownTypeName(r.typeNum())
	return s
}

func (t *table) print(duration *time.Duration) {
	if len(t.rows) > 0 {
		qtypeLen, qnameLen, ttlLen := 0, 0, 0
		for _, r := range t.rows {
			if r.qtypeLen > qtypeLen {
				qtypeLen = r.qtypeLen
			}
			if len(r.qname) > qnameLen {
				qnameLen = len(r.qname)
			}
			if r.ttl != nil && len(*r.ttl) > ttlLen {
				ttlLen = len(*r.ttl)
			}
		}
		for _, r := range t.rows {
			var b strings.Builder
			b.WriteString(strings.Repeat(" ", qtypeLen-r.qtypeLen))
			b.WriteString(r.qtype)
			b.WriteByte(' ')
			b.WriteString(t.pal.qname.paint(r.qname))
			b.WriteByte(' ')
			b.WriteString(strings.Repeat(" ", qnameLen-len(r.qname)))
			if r.ttl != nil {
				b.WriteString(strings.Repeat(" ", ttlLen-len(*r.ttl)))
				b.WriteString(*r.ttl)
			} else {
				b.WriteString(strings.Repeat(" ", ttlLen))
			}
			b.WriteByte(' ')
			switch r.section {
			case sectionAnswer:
				b.WriteString(t.pal.answer.paint(" "))
			case sectionAuthority:
				b.WriteString(t.pal.authority.paint("A"))
			case sectionAdditional:
				b.WriteString(t.pal.additional.paint("+"))
			}
			b.WriteByte(' ')
			b.WriteString(r.summary)
			b.WriteByte('\n')
			stdout.WriteString(b.String())
		}
	}
	if duration != nil {
		fmt.Fprintf(stdout, "Ran in %dms\n", duration.Milliseconds())
	}
}

func printErrorCode(rcode uint8) {
	switch rcode {
	case 1:
		stdout.WriteString("Status: Format Error\n")
	case 2:
		stdout.WriteString("Status: Server Failure\n")
	case 3:
		stdout.WriteString("Status: NXDomain\n")
	case 4:
		stdout.WriteString("Status: Not Implemented\n")
	case 5:
		stdout.WriteString("Status: Query Refused\n")
	default:
		fmt.Fprintf(stdout, "Status: Other Failure (%d)\n", rcode)
	}
}

// printResponses prints all the responses in the given format, returning
// false if there were no results in short mode.
func (f OutputFormat) printResponses(responses []*Response, duration *time.Duration) bool {
	defer stdout.Flush()
	switch f.kind {
	case FormatShort:
		tf := textFormat{formatDurations: f.formatDurations}
		var all []Answer
		for _, r := range responses {
			all = append(all, r.answers...)
		}
		if len(all) == 0 {
			stdout.Flush()
			os.Stderr.WriteString("No results\n")
			return false
		}
		for _, a := range all {
			if a.pseudo {
				stdout.WriteString(tf.pseudoSummary(a.opt) + "\n")
			} else {
				stdout.WriteString(tf.recordSummary(a.record) + "\n")
			}
		}
	case FormatJSON:
		var rs []string
		for _, r := range responses {
			rs = append(rs, "{"+
				jsonKey("queries")+jsonQueries(r.queries)+","+
				jsonKey("answers")+jsonAnswers(r.answers)+","+
				jsonKey("authorities")+jsonAnswers(r.authorities)+","+
				jsonKey("additionals")+jsonAnswers(r.additionals)+"}")
		}
		out := "{" + jsonKey("responses") + "[" + strings.Join(rs, ",") + "]"
		if duration != nil {
			d := *duration
			out += "," + jsonKey("duration") + "{" + jsonKey("secs") + strconv.FormatInt(int64(d/time.Second), 10) + "," +
				jsonKey("millis") + strconv.FormatInt(int64((d%time.Second)/time.Millisecond), 10) + "}"
		}
		out += "}\n"
		stdout.WriteString(out)
	case FormatText:
		t := &table{pal: newPalette(f.colours.shouldUseColours()), tf: textFormat{formatDurations: f.formatDurations}}
		for _, r := range responses {
			if r.flags.rcode != 0 {
				printErrorCode(r.flags.rcode)
			}
			for _, a := range r.answers {
				t.addRow(a, sectionAnswer)
			}
			for _, a := range r.authorities {
				t.addRow(a, sectionAuthority)
			}
			for _, a := range r.additionals {
				t.addRow(a, sectionAdditional)
			}
		}
		t.print(duration)
	}
	return true
}

func (f OutputFormat) printError(e *TransportError) {
	stdout.Flush()
	switch f.kind {
	case FormatJSON:
		os.Stderr.WriteString("{" + jsonKey("error") + "true," + jsonKey("error_phase") + jsonString(e.phase) + "," +
			jsonKey("error_message") + jsonString(e.msg) + "}\n")
	default:
		fmt.Fprintf(os.Stderr, "Error [%s]: %s\n", e.phase, e.msg)
	}
}

// ---- JSON ----

func jsonString(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch c {
		case '"':
			b.WriteString("\\\"")
		case '\\':
			b.WriteString("\\\\")
		case '\b':
			b.WriteString("\\b")
		case '\f':
			b.WriteString("\\f")
		case '\n':
			b.WriteString("\\n")
		case '\r':
			b.WriteString("\\r")
		case '\t':
			b.WriteString("\\t")
		default:
			if c < 0x20 {
				fmt.Fprintf(&b, "\\u%04x", c)
			} else {
				b.WriteByte(c)
			}
		}
	}
	b.WriteByte('"')
	return b.String()
}

func jsonKey(k string) string {
	return jsonString(k) + ":"
}

type jsonObj struct {
	parts []string
}

func (o *jsonObj) add(k, v string) *jsonObj {
	o.parts = append(o.parts, jsonKey(k)+v)
	return o
}

func (o *jsonObj) String() string {
	return "{" + strings.Join(o.parts, ",") + "}"
}

func jsonNum(n uint64) string { return strconv.FormatUint(n, 10) }

func jsonBool(b bool) string {
	if b {
		return "true"
	}
	return "false"
}

func jsonByteArray(b []byte) string {
	parts := make([]string, len(b))
	for i, x := range b {
		parts[i] = strconv.Itoa(int(x))
	}
	return "[" + strings.Join(parts, ",") + "]"
}

func jsonClass(c uint16) string {
	if s, ok := className(c); ok {
		return jsonString(s)
	}
	return jsonNum(uint64(c))
}

func jsonType(t uint16) string {
	if s, ok := knownTypeName(t); ok {
		return jsonString(s)
	}
	if t == 41 {
		return jsonString("OPT")
	}
	if s, ok := heardOfTypeName(t); ok {
		return jsonString(s)
	}
	return jsonNum(uint64(t))
}

func jsonQueries(qs []Query) string {
	parts := make([]string, len(qs))
	for i, q := range qs {
		o := &jsonObj{}
		o.add("name", jsonString(q.qname.String()))
		o.add("class", jsonClass(q.qclass))
		o.add("type", jsonType(q.qtype))
		parts[i] = o.String()
	}
