)

var stdout = bufio.NewWriterSize(os.Stdout, 8192)

// ---- ANSI styles ----

type style string

func (s style) paint(text string) string {
	if s == "" {
		return text
	}
	return "\x1b[" + string(s) + "m" + text + "\x1b[0m"
}

type palette struct {
	qname, answer, authority, additional style
	enabled                               bool
}

func newPalette(colour bool) palette {
	if !colour {
		return palette{}
	}
	return palette{qname: "1;34", answer: "", authority: "36", additional: "32", enabled: true}
}

func (p palette) typeStyle(t uint16, pseudo bool) style {
	if !p.enabled {
		return ""
	}
	if pseudo {
		return "35"
	}
	switch t {
	case 1, 28:
		return "1;32"
	case 257, 2, 12, 35:
		return "31"
	case 5, 108, 13, 29, 52, 16, 256:
		return "33"
	case 109:
		return "1;33"
	case 15, 61, 44, 33:
		return "36"
	case 6:
		return "35"
	}
	return "41;37"
}

// ---- Text table ----

type section int

const (
	sectionAnswer section = iota
	sectionAuthority
	sectionAdditional
)

type tableRow struct {
	qtype      string
	qtypeLen   int
	qname      string
	ttl        *string
	section    section
	summary    string
}

type table struct {
	pal  palette
	tf   textFormat
	rows []tableRow
}

func (t *table) addRow(a Answer, s section) {
	if a.pseudo {
		t.rows = append(t.rows, tableRow{
			qtype:    t.pal.typeStyle(41, true).paint("OPT"),
			qtypeLen: 3,
			qname:    a.qname.String(),
			section:  s,
			summary:  t.tf.pseudoSummary(a.opt),
		})
		return
	}
	n := a.record.typeNum()
	name := recordTypeName(a.record)
	ttl := t.tf.duration(a.ttl)
	t.rows = append(t.rows, tableRow{
		qtype:    t.pal.typeStyle(n, false).paint(name),
		qtypeLen: len(name),
		qname:    a.qname.String(),
		ttl:      &ttl,
		section:  s,
		summary:  t.tf.recordSummary(a.record),
	})
}

func recordTypeName(r Record) string {
	if o, ok := r.(recOther); ok {
		if s, ok := heardOfTypeName(o.num); ok {
			return s
		}
		return strconv.Itoa(int(o.num))
	}
	s, _ := knownTypeName(r.typeNum())
	return s
}

func (t *table) print(duration *time.Duration) {
	if len(t.rows) > 0 {
		qtypeLen, qnameLen, ttlLen := 0, 0, 0
		for _, r := range t.rows {
			if r.qtypeLen > qtypeLen {
				qtypeLen = r.qtypeLen
			}
			if len(r.qname) > qnameLen {
				qnameLen = len(r.qname)
			}
			if r.ttl != nil && len(*r.ttl) > ttlLen {
				ttlLen = len(*r.ttl)
			}
		}
		for _, r := range t.rows {
			var b strings.Builder
