import "C"

import (
	"errors"
	"net/netip"
	"strconv"
	"strings"
	"syscall"
	"time"
	"unsafe"
)

// ---- Rust-style io::Error ----

type ioError struct {
	errno  syscall.Errno
	custom string
	eof    bool
}

func (e *ioError) Error() string {
	if e.custom != "" {
		return e.custom
	}
	return strerror(e.errno) + " (os error " + strconv.Itoa(int(e.errno)) + ")"
}

func strerror(e syscall.Errno) string {
	buf := make([]byte, 256)
	p := C.dog_strerror(C.int(e), (*C.char)(unsafe.Pointer(&buf[0])), C.size_t(len(buf)))
	return C.GoString(p)
}

func osErr(err error) *ioError {
	var en syscall.Errno
	if errors.As(err, &en) {
		return &ioError{errno: en}
	}
	return &ioError{custom: err.Error()}
}

// ---- Address resolution, mimicking Rust's ToSocketAddrs ----

type sockAddr struct {
	ip   netip.Addr
	port uint16
}

func (a sockAddr) String() string {
	if a.ip.Is4() {
		return a.ip.String() + ":" + strconv.Itoa(int(a.port))
	}
	return "[" + a.ip.String() + "]:" + strconv.Itoa(int(a.port))
}

func parseRustIPv4(s string) (netip.Addr, bool) {
	a, err := netip.ParseAddr(s)
	if err != nil || !a.Is4() {
		return netip.Addr{}, false
	}
	return a, true
}

func parseRustIPv6(s string) (netip.Addr, bool) {
	if strings.Contains(s, "%") {
		return netip.Addr{}, false
	}
	a, err := netip.ParseAddr(s)
	if err != nil || !a.Is6() {
		return netip.Addr{}, false
	}
	return a, true
}

// parseRustSocketAddr parses "1.2.3.4:53" or "[::1]:53".
func parseRustSocketAddr(s string) (sockAddr, bool) {
	if strings.HasPrefix(s, "[") {
		end := strings.Index(s, "]")
		if end < 0 || end+1 >= len(s) || s[end+1] != ':' {
			return sockAddr{}, false
		}
		ip, ok := parseRustIPv6(s[1:end])
		if !ok {
			return sockAddr{}, false
		}
		p, ok := parseStrictPort(s[end+2:])
		if !ok {
			return sockAddr{}, false
		}
		return sockAddr{ip, p}, true
	}
	idx := strings.LastIndex(s, ":")
	if idx < 0 {
		return sockAddr{}, false
	}
	ip, ok := parseRustIPv4(s[:idx])
