	if readLen == 0 {
		logWarn(target, "Received no bytes!")
		return nil, errTruncated
	} else if readLen == 1 {
		logInfo(target, "Received one byte of data")
		second, err := s.Read(buf[1:])
		if err != nil {
			return nil, readErr(err)
		}
		if second == 0 {
			logWarn(target, "Received no bytes the second time!")
			return nil, errTruncated
		}
		readLen += second
	} else {
		logInfo(target, "Received %d bytes of data", readLen)
	}

	total := int(buf[0])<<8 | int(buf[1])
	if readLen-2 == total {
		logDebug(target, "We have enough bytes")
		return buf[2:readLen], nil
	}

	logDebug(target, "We need to read %d bytes total", total)
	combined := append([]byte(nil), buf[2:readLen]...)
	for len(combined) < total {
		ext := make([]byte, 4096)
		n, err := s.Read(ext)
		if err != nil {
			return nil, readErr(err)
		}
		logInfo(target, "Received further %d bytes of data (of %d)", n, total)
		if n == 0 {
			// The original keeps on looping when the stream has ended.
			hangForever()
		}
		combined = append(combined, ext[:n]...)
	}
	return combined, nil
}

func (t *tcpTransport) send(r *Request) (*Response, *TransportError) {
	logInfo("dns_transport::tcp", "Opening TCP stream")
	addrs, ierr := resolveNameserver(t.addr, 53)
	if ierr != nil {
		return nil, networkError(ierr)
	}
	conn, ierr := tcpConnect(addrs)
	if ierr != nil {
		return nil, networkError(ierr)
	}
	defer conn.Close()
	logDebug("dns_transport::tcp", "Opened")

	bytes := prefixWithLength(r.toWire())
	logInfo("dns_transport::tcp", "Sending %d bytes of data to %s over TCP", len(bytes), rustDebugStr(t.addr))
	n, err := conn.Write(bytes)
	if err != nil {
		return nil, readErr(err)
	}
	logDebug("dns_transport::tcp", "Wrote %d bytes", n)

	data, terr := lengthPrefixedRead(conn, "dns_transport::tcp")
	if terr != nil {
		return nil, terr
	}
	resp, werr := parseResponse(data)
	if werr != nil {
		return nil, wireError(werr)
	}
	return resp, nil
}

// ---- Automatic ----

type autoTransport struct{ addr string }

func (t *autoTransport) send(r *Request) (*Response, *TransportError) {
	udp := &udpTransport{t.addr}
	resp, err := udp.send(r)
	if err != nil {
		return nil, err
	}
	if !resp.flags.truncated {
		return resp, nil
	}
	logDebug("dns_transport::auto", "Truncated flag set, so switching to TCP")
	tcp := &tcpTransport{t.addr}
	return tcp.send(r)
}

// ---- TLS ----

type tlsTransport struct{ addr string }

// netConnAdapter wraps a raw connection to make it usable by crypto/tls.
type netConnAdapter struct {
	c *rawConn
}

func (a *netConnAdapter) Read(b []byte) (int, error)         { return a.c.Read(b) }
func (a *netConnAdapter) Write(b []byte) (int, error)        { return a.c.Write(b) }
func (a *netConnAdapter) Close() error                       { return a.c.Close() }
func (a *netConnAdapter) LocalAddr() net.Addr                { return &net.TCPAddr{} }
func (a *netConnAdapter) RemoteAddr() net.Addr               { return &net.TCPAddr{} }
func (a *netConnAdapter) SetDeadline(t time.Time) error      { return nil }
func (a *netConnAdapter) SetReadDeadline(t time.Time) error  { return nil }
func (a *netConnAdapter) SetWriteDeadline(t time.Time) error { return nil }

type rustParseIntError string

func panicRust(location, msg string) {
	os.Stderr.WriteString(fmt.Sprintf("\nthread 'main' (%d) panicked at %s:\n%s\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n", os.Getpid(), location, msg))
	rustAbort()
}

func rustParseU16Error(s string) string {
	if s == "" {
		return "ParseIntError { kind: Empty }"
	}
	t := s
	if t[0] == '+' {
		t = t[1:]
		if t == "" {
			return "ParseIntError { kind: InvalidDigit }"
		}
	}
	for _, c := range t {
		if c < '0' || c > '9' {
			return "ParseIntError { kind: InvalidDigit }"
		}
	}
	return "ParseIntError { kind: PosOverflow }"
}

func tlsStream(domain string, port uint16) (*tls.Conn, *TransportError) {
	addrs, ierr := resolveHostPort(domain, port)
	if ierr != nil {
		return nil, networkError(ierr)
	}
	raw, ierr := tcpConnect(addrs)
	if ierr != nil {
		return nil, networkError(ierr)
	}
	cfg := &tls.Config{ServerName: domain}
	if _, ok := parseRustIPv4(domain); ok {
		cfg.ServerName = domain
	}
	conn := tls.Client(&netConnAdapter{raw}, cfg)
	if err := conn.Handshake(); err != nil {
		raw.Close()
		return nil, &TransportError{phase: "tls", msg: tlsErrorMessage(err, domain)}
	}
	return conn, nil
}

func (t *tlsTransport) sniDomain() string {
	if i := strings.Index(t.addr, ":"); i >= 0 {
		return t.addr[:i]
	}
	return t.addr
}

func (t *tlsTransport) send(r *Request) (*Response, *TransportError) {
	logInfo("dns_transport::tls", "Opening TLS socket")
	domain := t.sniDomain()
	logInfo("dns_transport::tls", "Connecting using domain %s", rustDebugStr(domain))
	var conn *tls.Conn
	var terr *TransportError
	if strings.Contains(t.addr, ":") {
		parts := strings.Split(t.addr, ":")
		d := parts[0]
		portStr := parts[len(parts)-1]
		port, ok := parseRustU16(portStr, 10)
		if !ok {
			panicRust("dns-transport/src/tls.rs:41:65", "Invalid port number: "+rustParseU16Error(portStr))
		}
		conn, terr = tlsStream(d, port)
	} else {
		conn, terr = tlsStream(t.addr, 853)
	}
	if terr != nil {
		return nil, terr
	}
	defer conn.Close()
	logDebug("dns_transport::tls", "Connected")

	bytes := prefixWithLength(r.toWire())
	logInfo("dns_transport::tls", "Sending %d bytes of data to %s over TLS", len(bytes), t.addr)
	if _, err := conn.Write(bytes); err != nil {
		return nil, tlsIOError(err)
	}
	logDebug("dns_transport::tls", "Wrote all bytes")

	data, rerr := lengthPrefixedRead(&tlsReader{conn}, "dns_transport::tls")
	if rerr != nil {
		return nil, rerr
	}
	resp, werr := parseResponse(data)
	if werr != nil {
		return nil, wireError(werr)
	}
	return resp, nil
}

// tlsReader converts TLS-level EOF conditions into zero-byte reads, the
// way OpenSSL streams report them.
type tlsReader struct {
	c *tls.Conn
}

func (r *tlsReader) Read(b []byte) (int, error) {
	n, err := r.c.Read(b)
	if err != nil {
		if n > 0 {
			return n, nil
		}
		if errors.Is(err, io.EOF) || errors.Is(err, io.ErrUnexpectedEOF) {
			return 0, nil
		}
		var ie *ioError
		if errors.As(err, &ie) {
			return 0, ie
		}
		return 0, &ioError{custom: tlsErrorMessage(err, "")}
	}
	return n, nil
}

func tlsIOError(err error) *TransportError {
	var ie *ioError
	if errors.As(err, &ie) {
		return networkError(ie)
	}
	return &TransportError{phase: "network", msg: tlsErrorMessage(err, "")}
}

const sslVerifyFailed = "error:1416F086:SSL routines:tls_process_server_certificate:certificate verify failed:ssl/statem/statem_clnt.c:1913:"

var alertDescriptions = map[uint8]string{
	0:   "close notify",
	10:  "unexpected message",
	20:  "bad record mac",
	21:  "decryption failed",
	22:  "record overflow",
	30:  "decompression failure",
	40:  "handshake failure",
	41:  "no certificate",
	42:  "bad certificate",
	43:  "unsupported certificate",
	44:  "certificate revoked",
	45:  "certificate expired",
	46:  "certificate unknown",
	47:  "illegal parameter",
	48:  "unknown ca",
	49:  "access denied",
	50:  "decode error",
	51:  "decrypt error",
	60:  "export restriction",
	70:  "protocol version",
	71:  "insufficient security",
	80:  "internal error",
	86:  "inappropriate fallback",
	90:  "user canceled",
	100: "no renegotiation",
	109: "missing extension",
	110: "unsupported extension",
	111: "certificate unobtainable",
	112: "unrecognized name",
	113: "bad certificate status response",
	114: "bad certificate hash value",
	115: "unknown psk identity",
	116: "certificate required",
	120: "no application protocol",
}

func tlsErrorMessage(err error, domain string) string {
	var cve *tls.CertificateVerificationError
	if errors.As(err, &cve) {
		reason := "certificate verify failed"
		var uae x509.UnknownAuthorityError
		var he x509.HostnameError
		var cie x509.CertificateInvalidError
		switch {
		case errors.As(cve.Err, &uae):
			reason = "unable to get local issuer certificate"
			if len(cve.UnverifiedCertificates) > 0 {
				leaf := cve.UnverifiedCertificates[0]
				if len(cve.UnverifiedCertificates) == 1 && leaf.CheckSignatureFrom(leaf) == nil && string(leaf.RawIssuer) == string(leaf.RawSubject) {
					reason = "self signed certificate"
				} else {
					last := cve.UnverifiedCertificates[len(cve.UnverifiedCertificates)-1]
					if string(last.RawIssuer) == string(last.RawSubject) && last.CheckSignatureFrom(last) == nil {
						reason = "self signed certificate in certificate chain"
					}
				}
			}
		case errors.As(cve.Err, &he):
			if _, ok := parseRustIPv4(he.Host); ok {
				reason = "IP address mismatch"
			} else if _, ok := parseRustIPv6(he.Host); ok {
				reason = "IP address mismatch"
			} else {
				reason = "Hostname mismatch"
			}
		case errors.As(cve.Err, &cie):
			switch cie.Reason {
			case x509.Expired:
				if len(cve.UnverifiedCertificates) > 0 && time.Now().Before(cve.UnverifiedCertificates[0].NotBefore) {
					reason = "certificate is not yet valid"
				} else {
					reason = "certificate has expired"
				}
			case x509.NotAuthorizedToSign:
				reason = "invalid CA certificate"
			case x509.IncompatibleUsage:
				reason = "unsupported certificate purpose"
			}
		}
		return sslVerifyFailed + " (" + reason + ")"
	}
	var ie *ioError
	if errors.As(err, &ie) {
		return ie.Error()
	}
	if errors.Is(err, io.EOF) || errors.Is(err, io.ErrUnexpectedEOF) {
		return "unexpected EOF"
	}
	var rhe tls.RecordHeaderError
	if errors.As(err, &rhe) {
		return "error:1408F10B:SSL routines:ssl3_get_record:wrong version number:ssl/record/ssl3_record.c:331:"
	}
	var oe *net.OpError
	if errors.As(err, &oe) && oe.Op == "remote error" {
		v := reflect.ValueOf(oe.Err)
		if v.Kind() == reflect.Uint8 {
			a := uint8(v.Uint())
			desc, ok := alertDescriptions[a]
			if !ok {
				desc = "unknown"
			}
			return fmt.Sprintf("error:%08X:SSL routines:ssl3_read_bytes:sslv3 alert %s:ssl/record/rec_layer_s3.c:1544:SSL alert number %d", 0x14094000+1000+int(a), strings.ReplaceAll(desc, " ", " "), a)
		}
	}
	var en syscall.Errno
	if errors.As(err, &en) {
		return (&ioError{errno: en}).Error()
	}
	return err.Error()
}

// ---- HTTPS ----

type httpsTransport struct{ url string }

func (t *httpsTransport) splitDomain() (string, string, bool) {
	if sp, ok := strings.CutPrefix(t.url, "https://"); ok {
		if i := strings.Index(sp, "/"); i >= 0 {
			return sp[:i], sp[i:], true
		}
	}
	return "", "", false
}

func (t *httpsTransport) send(r *Request) (*Response, *TransportError) {
	domain, path, ok := t.splitDomain()
	if !ok {
		panicRust("dns-transport/src/https.rs:42:50", "Invalid HTTPS nameserver")
	}
	logInfo("dns_transport::https", "Opening TLS socket to %s", rustDebugStr(domain))
	addrs, ierr := resolveString(domain + ":443")
	if ierr != nil {
		return nil, networkError(ierr)
	}
	raw, ierr := tcpConnect(addrs)
	if ierr != nil {
		return nil, networkError(ierr)
	}
	conn := tls.Client(&netConnAdapter{raw}, &tls.Config{ServerName: domain})
	if err := conn.Handshake(); err != nil {
		raw.Close()
		return nil, &TransportError{phase: "tls", msg: tlsErrorMessage(err, domain)}
	}
	defer conn.Close()
	logDebug("dns_transport::https", "Connected")

	body := r.toWire()
	req := "POST " + path + " HTTP/1.1\r\n" +
		"Host: " + domain + "\r\n" +
		"Content-Type: application/dns-message\r\n" +
		"Accept: application/dns-message\r\n" +
		"User-Agent: dog/" + versionString + "\r\n" +
		"Content-Length: " + strconv.Itoa(len(body)) + "\r\n\r\n"
	toSend := append([]byte(req), body...)
	logInfo("dns_transport::https", "Sending %d bytes of data to %s over HTTPS", len(toSend), rustDebugStr(t.url))
	if _, err := conn.Write(toSend); err != nil {
		return nil, tlsIOError(err)
	}
	logDebug("dns_transport::https", "Wrote all bytes")

	logInfo("dns_transport::https", "Waiting to receive...")
	rd := &tlsReader{conn}
	buf := make([]byte, 4096)
	n, err := rd.Read(buf)
	if err != nil {
		return nil, readErr(err)
	}
	logInfo("dns_transport::https", "Received %d bytes of data", n)
	data := buf[:n]

	var hr *httpResponse
	for {
		var perr error
		var complete bool
		hr, complete, perr = parseHTTPResponse(data)
		if perr != nil {
			return nil, &TransportError{phase: "http", msg: perr.Error()}
		}
		if complete {
			break
		}
		more := make([]byte, 4096)
		m, err := rd.Read(more)
		if err != nil {
			return nil, readErr(err)
		}
		if m == 0 {
			hangForever()
		}
		data = append(data, more[:m]...)
	}

	if hr.code != 200 {
		return nil, &TransportError{phase: "http", msg: fmt.Sprintf("Nameserver returned HTTP %d (%s)", hr.code, hr.reason)}
	}

	contentLength := -1
	for _, h := range hr.headers {
		logDebug("dns_transport::https", "Header %s -> %s", rustDebugStr(h.name), rustDebugStr(rustLossy(h.value)))
		if strings.EqualFold(h.name, "Content-Length") {
			if v, err := strconv.Atoi(strings.TrimSpace(string(h.value))); err == nil {
				contentLength = v
			}
		}
	}
	respBody := data[hr.headerLen:]
	if contentLength >= 0 {
		for len(respBody) < contentLength {
			more := make([]byte, 4096)
			m, err := rd.Read(more)
			if err != nil {
				return nil, readErr(err)
			}
			if m == 0 {
				hangForever()
			}
			respBody = append(respBody, more[:m]...)
		}
		respBody = respBody[:contentLength]
	}
	logDebug("dns_transport::https", "HTTP body has %d bytes", len(respBody))
	resp, werr := parseResponse(respBody)
	if werr != nil {
		return nil, wireError(werr)
	}
	return resp, nil
}

// ---- Minimal HTTP response parser ----

type httpHeader struct {
	name  string
	value []byte
}

type httpResponse struct {
	code      int
	reason    string
	headers   []httpHeader
	headerLen int
}

type httpParseError string

func (e httpParseError) Error() string { return string(e) }

func isTokenChar(c byte) bool {
	if c <= 0x20 || c >= 0x7f {
		return false
	}
	switch c {
	case '(', ')', '<', '>', '@', ',', ';', ':', '\\', '"', '/', '[', ']', '?', '=', '{', '}':
		return false
	}
	return true
}

// parseHTTPResponse parses the head of an HTTP response, returning
// complete=false if more data is needed.
func parseHTTPResponse(b []byte) (*httpResponse, bool, error) {
	i := 0
	// Skip empty lines
	for i < len(b) {
		if b[i] == '\r' {
			if i+1 >= len(b) {
				return nil, false, nil
			}
			if b[i+1] != '\n' {
				return nil, false, httpParseError("invalid new line")
			}
			i += 2
		} else if b[i] == '\n' {
			i++
		} else {
			break
		}
	}
	// Version
	const ver = "HTTP/1."
	for j := 0; j < len(ver); j++ {
		if i+j >= len(b) {
			return nil, false, nil
		}
		if b[i+j] != ver[j] {
			return nil, false, httpParseError("invalid HTTP version")
		}
	}
	i += len(ver)
	if i >= len(b) {
		return nil, false, nil
	}
	if b[i] != '0' && b[i] != '1' {
		return nil, false, httpParseError("invalid HTTP version")
	}
	i++
	if i >= len(b) {
		return nil, false, nil
	}
	if b[i] != ' ' {
		return nil, false, httpParseError("invalid HTTP version")
	}
	i++
	// Status code
	code := 0
	for j := 0; j < 3; j++ {
		if i >= len(b) {
			return nil, false, nil
		}
		if b[i] < '0' || b[i] > '9' {
			return nil, false, httpParseError("invalid response status")
		}
		code = code*10 + int(b[i]-'0')
		i++
	}
	if i >= len(b) {
		return nil, false, nil
	}
	resp := &httpResponse{code: code}
	switch b[i] {
	case ' ':
		i++
		start := i
		for {
			if i >= len(b) {
				return nil, false, nil
			}
			c := b[i]
			if c == '\r' {
				if i+1 >= len(b) {
					return nil, false, nil
				}
				if b[i+1] != '\n' {
					return nil, false, httpParseError("invalid response status")
				}
				resp.reason = string(b[start:i])
				i += 2
				break
			} else if c == '\n' {
				resp.reason = string(b[start:i])
				i++
				break
			} else if !(c == '\t' || c == ' ' || (c >= 0x21 && c != 0x7f)) {
				return nil, false, httpParseError("invalid response status")
			}
			i++
		}
	case '\r':
		if i+1 >= len(b) {
			return nil, false, nil
		}
		if b[i+1] != '\n' {
			return nil, false, httpParseError("invalid response status")
		}
		i += 2
	case '\n':
		i++
	default:
		return nil, false, httpParseError("invalid response status")
	}
	// Headers
	for {
		if i >= len(b) {
			return nil, false, nil
		}
		if b[i] == '\r' {
			if i+1 >= len(b) {
				return nil, false, nil
			}
			if b[i+1] != '\n' {
				return nil, false, httpParseError("invalid new line")
			}
			i += 2
			break
		}
		if b[i] == '\n' {
			i++
			break
		}
		if len(resp.headers) >= 16 {
			return nil, false, httpParseError("too many headers")
		}
		start := i
		for {
			if i >= len(b) {
				return nil, false, nil
			}
			if b[i] == ':' {
				break
			}
			if !isTokenChar(b[i]) {
				return nil, false, httpParseError("invalid header name")
			}
			i++
		}
		name := string(b[start:i])
		if name == "" {
			return nil, false, httpParseError("invalid header name")
		}
		i++
		for {
			if i >= len(b) {
				return nil, false, nil
			}
			if b[i] != ' ' && b[i] != '\t' {
				break
			}
			i++
		}
		vstart := i
		var value []byte
		for {
			if i >= len(b) {
				return nil, false, nil
			}
			c := b[i]
			if c == '\r' {
				if i+1 >= len(b) {
					return nil, false, nil
				}
				if b[i+1] != '\n' {
					return nil, false, httpParseError("invalid header value")
				}
				value = b[vstart:i]
				i += 2
				break
			} else if c == '\n' {
				value = b[vstart:i]
				i++
				break
			} else if !(c == '\t' || (c >= 0x20 && c != 0x7f)) {
				return nil, false, httpParseError("invalid header value")
			}
			i++
		}
		// Trim trailing whitespace
		for len(value) > 0 && (value[len(value)-1] == ' ' || value[len(value)-1] == '\t') {
			value = value[:len(value)-1]
		}
		resp.headers = append(resp.headers, httpHeader{name, value})
	}
	resp.headerLen = i
	return resp, true, nil
}
