package main

import (
	"bufio"
	"crypto/rand"
	"encoding/binary"
	"fmt"
	"os"
	"strings"
	"time"
)

const (
	exitSuccess        = 0
	exitNetworkError   = 1
	exitNoShortResults = 2
	exitOptionsError   = 3
	exitSystemError    = 4
)

func main() {
	configureLogger()
	res := parseOptions(os.Args[1:])
	switch res.kind {
	case resultOk:
		logInfo("dog", "Running with options -> %s", res.opts.debugString())
		os.Exit(run(res.opts))
	case resultHelpFlag:
		printHelp(res.colours)
		os.Exit(exitSuccess)
	case resultHelpNoDomains:
		printHelp(res.colours)
		os.Exit(exitOptionsError)
	case resultVersion:
		printVersion(res.colours)
		os.Exit(exitSuccess)
	case resultInvalid:
		fmt.Fprintf(os.Stderr, "dog: Invalid options: %s\n", res.err)
		os.Exit(exitOptionsError)
	}
}

func randomTxid() uint16 {
	var b [2]byte
	rand.Read(b[:])
	return binary.BigEndian.Uint16(b[:])
}

type requestBatch struct {
	transport Transport
	requests  []*Request
}

func systemNameserver() (string, error) {
	f, err := os.Open("/etc/resolv.conf")
	if err != nil {
		return "", osErr(err)
	}
	defer f.Close()
	var nameservers []string
	sc := bufio.NewScanner(f)
	for sc.Scan() {
		line := sc.Text()
		if rest, ok := strings.CutPrefix(line, "nameserver "); ok {
			if _, ok := parseRustIPv4(rest); ok {
				nameservers = append(nameservers, rest)
			} else if _, ok := parseRustIPv6(rest); ok {
				nameservers = append(nameservers, rest)
			} else {
				logWarn("dog::resolve", "Failed to parse nameserver line %s", rustDebugStr(line))
			}
		}
	}
	if len(nameservers) == 0 {
		return "", fmt.Errorf("No nameserver found")
	}
	return nameservers[0], nil
}

func (rg *RequestGenerator) generate() ([]requestBatch, error) {
	var batches []requestBatch
	var sysNS *string
	for _, domain := range rg.inputs.domains {
		for _, qtype := range rg.inputs.recordTypes {
			for _, qclass := range rg.inputs.classes {
				for _, rt := range rg.inputs.resolverTypes {
					addr := rt.addr
					if rt.systemDefault {
						if sysNS == nil {
							ns, err := systemNameserver()
							if err != nil {
								return nil, err
							}
							sysNS = &ns
						}
						addr = *sysNS
					}
					for _, tt := range rg.inputs.transportTypes {
						txid := rg.txid
						if !rg.txidSet {
							txid = randomTxid()
						}
						flags := uint16(0x0100)
						if rg.tweaks.setAuthoritative {
							flags |= 0x0400
						}
						if rg.tweaks.setAuthentic {
							flags |= 0x0020
						}
						if rg.tweaks.setCheckingDisabled {
							flags |= 0x0010
						}
						req := &Request{
							txid:   txid,
							flags:  flags,
							name:   domain,
							qtype:  qtype,
							qclass: qclass,
							edns:   rg.edns != EDNSDisable,
						}
						req.udpSize = 512
						if rg.tweaks.udpPayloadSize != nil {
							req.udpSize = *rg.tweaks.udpPayloadSize
						}
						batches = append(batches, requestBatch{newTransport(tt, addr), []*Request{req}})
					}
				}
			}
		}
	}
	return batches, nil
}

func filterStandard(as []Answer) []Answer {
	out := as[:0]
	for _, a := range as {
		if !a.pseudo {
			out = append(out, a)
		}
	}
	return out
}

func run(o *Options) int {
	shouldShowOpt := o.requests.edns == EDNSSendAndShow
	var responses []*Response
	var timer time.Time
	if o.measureTime {
		timer = time.Now()
	}
	errored := false

	hints := loadLocalHosts()
	for _, d := range o.requests.inputs.domains {
		if hints.contains(d) {
			fmt.Fprintf(os.Stderr, "warning: domain '%s' also exists in hosts file\n", d.String())
		}
	}

	batches, err := o.requests.generate()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Unable to obtain resolver: %s\n", err.Error())
		return exitSystemError
	}

	for _, b := range batches {
		for i, req := range b.requests {
			resp, terr := b.transport.send(req)
			if terr != nil {
				o.format.printError(terr)
				errored = true
				break
			}
			if resp.flags.rcode != 0 && i != len(b.requests)-1 {
				continue
			}
			if !shouldShowOpt {
				resp.answers = filterStandard(resp.answers)
				resp.authorities = filterStandard(resp.authorities)
				resp.additionals = filterStandard(resp.additionals)
			}
			responses = append(responses, resp)
			break
		}
	}

	var dur *time.Duration
	if o.measureTime {
		d := time.Since(timer)
		dur = &d
	}
	if o.format.printResponses(responses, dur) {
		if errored {
			return exitNetworkError
		}
		return exitSuccess
	}
	return exitNoShortResults
}

// ---- Debug representation of the options ----

func (o *Options) debugString() string {
	var b strings.Builder
	in := o.requests.inputs
	b.WriteString("Options {\n")
	b.WriteString("    requests: RequestGenerator {\n")
	b.WriteString("        inputs: Inputs {\n")
	b.WriteString("            domains: [")
	if len(in.domains) > 0 {
		b.WriteString("\n")
		for _, d := range in.domains {
			b.WriteString("                Labels {\n")
			b.WriteString("                    segments: [")
			if len(d.segments) > 0 {
				b.WriteString("\n")
				for _, s := range d.segments {
					b.WriteString("                        (\n")
					fmt.Fprintf(&b, "                            %d,\n", s.length)
					fmt.Fprintf(&b, "                            %s,\n", rustDebugStr(s.text))
					b.WriteString("                        ),\n")
				}
				b.WriteString("                    ")
			}
			b.WriteString("],\n")
			b.WriteString("                },\n")
		}
		b.WriteString("            ")
	}
	b.WriteString("],\n")
	b.WriteString("            record_types: [\n")
	for _, t := range in.recordTypes {
		b.WriteString("                " + debugQType(t, "                ") + ",\n")
	}
	b.WriteString("            ],\n")
	b.WriteString("            classes: [\n")
	for _, c := range in.classes {
		if s, ok := className(uint16(c)); ok {
			b.WriteString("                " + s + ",\n")
		} else {
			fmt.Fprintf(&b, "                Other(\n                    %d,\n                ),\n", c)
		}
	}
	b.WriteString("            ],\n")
	b.WriteString("            resolver_types: [\n")
	for _, r := range in.resolverTypes {
		if r.systemDefault {
			b.WriteString("                SystemDefault,\n")
		} else {
			fmt.Fprintf(&b, "                Specific(\n                    %s,\n                ),\n", rustDebugStr(r.addr))
		}
	}
	b.WriteString("            ],\n")
	b.WriteString("            transport_types: [\n")
	for _, t := range in.transportTypes {
		b.WriteString("                " + t.debugName() + ",\n")
	}
	b.WriteString("            ],\n")
	b.WriteString("        },\n")
	if o.requests.txidSet {
		fmt.Fprintf(&b, "        txid_generator: Sequence(\n            %d,\n        ),\n", o.requests.txid)
	} else {
		b.WriteString("        txid_generator: Random,\n")
	}
	b.WriteString("        edns: " + o.requests.edns.debugName() + ",\n")
	tw := o.requests.tweaks
	b.WriteString("        protocol_tweaks: ProtocolTweaks {\n")
	fmt.Fprintf(&b, "            set_authoritative_flag: %v,\n", tw.setAuthoritative)
	fmt.Fprintf(&b, "            set_authentic_flag: %v,\n", tw.setAuthentic)
	fmt.Fprintf(&b, "            set_checking_disabled_flag: %v,\n", tw.setCheckingDisabled)
	if tw.udpPayloadSize != nil {
		fmt.Fprintf(&b, "            udp_payload_size: Some(\n                %d,\n            ),\n", *tw.udpPayloadSize)
	} else {
		b.WriteString("            udp_payload_size: None,\n")
	}
	b.WriteString("        },\n")
	b.WriteString("    },\n")
	fmt.Fprintf(&b, "    measure_time: %v,\n", o.measureTime)
	switch o.format.kind {
	case FormatJSON:
		b.WriteString("    format: JSON,\n")
	case FormatShort:
		b.WriteString("    format: Short(\n        TextFormat {\n")
		fmt.Fprintf(&b, "            format_durations: %v,\n", o.format.formatDurations)
		b.WriteString("        },\n    ),\n")
	case FormatText:
		b.WriteString("    format: Text(\n        " + o.format.colours.debugName() + ",\n        TextFormat {\n")
		fmt.Fprintf(&b, "            format_durations: %v,\n", o.format.formatDurations)
		b.WriteString("        },\n    ),\n")
	}
	b.WriteString("}")
	return b.String()
}
