// verifyLikeOpenSSL verifies the peer certificates, reporting errors in
// the same order and with the same wording as OpenSSL.
func verifyLikeOpenSSL(certs []*x509.Certificate, domain string) error {
	if len(certs) == 0 {
		return &verifyError{"unable to get local issuer certificate"}
	}
	leaf := certs[0]
	roots, err := x509.SystemCertPool()
	if err != nil || roots == nil {
		roots = x509.NewCertPool()
	}
	inter := x509.NewCertPool()
	for _, c := range certs[1:] {
		inter.AddCert(c)
	}
	// Chain building, ignoring validity periods.
	checkTime := leaf.NotBefore.Add(time.Second)
	if checkTime.After(leaf.NotAfter) {
		checkTime = leaf.NotBefore
	}
	_, verr := leaf.Verify(x509.VerifyOptions{
		Roots:         roots,
		Intermediates: inter,
		CurrentTime:   checkTime,
		KeyUsages:     []x509.ExtKeyUsage{x509.ExtKeyUsageAny},
	})
	if verr != nil {
		var uae x509.UnknownAuthorityError
		if errors.As(verr, &uae) {
			if len(certs) == 1 && isSelfSigned(leaf) {
				return &verifyError{"self signed certificate"}
			}
			if isSelfSigned(certs[len(certs)-1]) {
				return &verifyError{"self signed certificate in certificate chain"}
			}
			return &verifyError{"unable to get local issuer certificate"}
		}
		var cie x509.CertificateInvalidError
		if errors.As(verr, &cie) {
			switch cie.Reason {
			case x509.NotAuthorizedToSign:
				return &verifyError{"invalid CA certificate"}
			case x509.IncompatibleUsage:
				return &verifyError{"unsupported certificate purpose"}
			}
		}
		if !errors.As(verr, &cie) {
			return &verifyError{"certificate verify failed"}
		}
	}
	// Host name / IP address checks.
	if ip, ok := parseRustIPv4(domain); ok {
		if !certHasIP(leaf, ip.String()) {
			return &verifyError{"IP address mismatch"}
		}
	} else if ip, ok := parseRustIPv6(domain); ok {
		if !certHasIP(leaf, ip.String()) {
			return &verifyError{"IP address mismatch"}
		}
	} else {
		if len(leaf.DNSNames) > 0 {
			if leaf.VerifyHostname(domain) != nil {
				return &verifyError{"Hostname mismatch"}
			}
		} else if !strings.EqualFold(leaf.Subject.CommonName, domain) {
			return &verifyError{"Hostname mismatch"}
		}
	}
	// Validity periods.
	now := time.Now()
	for _, c := range certs {
		if now.Before(c.NotBefore) {
			return &verifyError{"certificate is not yet valid"}
		}
		if now.After(c.NotAfter) {
			return &verifyError{"certificate has expired"}
		}
	}
	return nil
}

