		}
		if x.String() == ip {
			return true
		}
	}
	return false
}

func tlsErrorMessage(err error, domain string) string {
	var ve *verifyError
	if errors.As(err, &ve) {
		return sslVerifyFailed + " (" + ve.reason + ")"
	}
