//go:build !cgo

package main

import (
	"context"
	"errors"
	"net"
	"net/netip"
	"strings"
	"syscall"
)

func strerror(e syscall.Errno) string {
	s := e.Error()
	if s == "" {
		return s
	}
	return strings.ToUpper(s[:1]) + s[1:]
}

// lookupHost resolves a host name using Go's resolver, describing errors
// the way getaddrinfo would.
func lookupHost(host string, port uint16) ([]sockAddr, *ioError) {
	if strings.IndexByte(host, 0) >= 0 {
		return nil, &ioError{custom: "file name contained an unexpected NUL byte"}
	}
	if host == "" {
		return nil, &ioError{custom: "failed to lookup address information: Name or service not known"}
	}
	addrs, err := net.DefaultResolver.LookupIPAddr(context.Background(), host)
	if err != nil {
		var de *net.DNSError
		if errors.As(err, &de) && de.IsNotFound {
			return nil, &ioError{custom: "failed to lookup address information: Name or service not known"}
		}
		return nil, &ioError{custom: "failed to lookup address information: Temporary failure in name resolution"}
	}
	var out []sockAddr
	for _, a := range addrs {
		ip, ok := netip.AddrFromSlice(a.IP)
		if !ok {
			continue
		}
		if ip.Is4In6() {
			ip = ip.Unmap()
		}
		out = append(out, sockAddr{ip, port})
	}
	return out, nil
}
EOF
